{"command":"python3 <<'PY'
import math
obs=[0,0,28,93,162,227,255,255]
def sinc(x):
    if x==0: return 1
    return math.sin(math.pi*x)/(math.pi*x)
def lanczos(a):
    def k(x):
        x=abs(x)
        if x<a: return sinc(x)*sinc(x/a)
        return 0
    return k
def bilinear(x):
    x=abs(x); return max(0,1-x)
def bicubic(x): # Catmull-Rom a=-0.5 Keys
    a=-0.5; x=abs(x)
    if x<1: return (a+2)*x**3-(a+3)*x**2+1
    if x<2: return a*x**3-5*a*x**2+8*a*x-4*a
    return 0
def mitchell(x):
    B=1/3; C=1/3; x=abs(x)
    if x<1:
        return ((12-9*B-6*C)*x**3+(-18+12*B+6*C)*x**2+(6-2*B))/6
    if x<2:
        return ((-B-6*C)*x**3+(6*B+30*C)*x**2+(-12*B-48*C)*x+(8*B+24*C))/6
    return 0
def bspline(x):
    x=abs(x)
    if x<1: return 2/3 - x**2 + x**3/2
    if x<2: return (2-x)**3/6
    return 0
def hermite(x):
    x=abs(x)
    return (2*x-3)*x*x+1 if x<1 else 0
kernels={"bilinear":bilinear,"bicubic":bicubic,"mitchell":mitchell,"lanczos2":lanczos(2),"lanczos3":lanczos(3),"bspline":bspline}
def predict(kernel,invals,outn,mode="truncate_normalize"):
    inn=len(invals); scale=inn/outn; out=[]
    # support scale for downscale maybe kernel scaled by scale if scale>1
    for j in range(outn):
        src=(j+0.5)*scale-0.5
        total=0; wsum=0
        # consider input indices maybe -10..inn+9 with modes
        for i in range(-10,inn+10):
            d=src-i
            # for upscale support unscaled
            w=kernel(d)
            if w==0: continue
            if mode=="truncate_normalize":
                if i<0 or i>=inn: continue
                val=invals[i]
            elif mode=="clamp":
                val=invals[min(max(i,0),inn-1)]
            elif mode=="truncate_no_norm":
                if i<0 or i>=inn: continue
                val=invals[i]; wsum=1; total+=w*val; continue
            total+=w*val; wsum+=w
        if mode!="truncate_no_norm": total/=wsum if wsum else 1
        out.append(round(total))
    return out
for name,k in kernels.items():
    for mode in ["truncate_normalize","clamp","truncate_no_norm"]:
        print(name,mode,predict(k,[0,255],8,mode))
print("obs",obs)
PY
"}

