{"command":"cat > /tmp/pty_run.py <<'PY'
import os, pty, subprocess, fcntl, termios, struct, sys, select
def run_pty(args, cols=80, rows=24, stdout_tty=True, stdin_tty=False, stderr_tty=True, env_extra={}):
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0, 0))
    # separate pty for stdin if needed?
    master2=slave2=None
    if stdin_tty:
        master2, slave2 = pty.openpty()
        fcntl.ioctl(slave2, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0, 0))
        stdin=slave2
    else:
        stdin=subprocess.PIPE
    env=dict(os.environ)
    env.update(env_extra)
    p=subprocess.Popen(["./executable"]+args, stdout=slave if stdout_tty else subprocess.PIPE, stderr=slave if stderr_tty else subprocess.PIPE, stdin=stdin, close_fds=True, env=env)
    os.close(slave)
    if slave2 is not None: os.close(slave2)
    out=b""
    # if stdout piped, master is only stderr
    # read master nonblocking until proc ends
    # Simplify: if stdout_tty read master; else communicate
    if stdout_tty:
        while True:
            try:
                r,_,_=select.select([master],[],[],0.1)
                if master in r:
                    d=os.read(master,65536)
                    if not d: break
                    out+=d
                if p.poll() is not None:
                    # drain
                    try:
                        while True:
                            d=os.read(master,65536)
                            if not d: break
                            out+=d
                    except OSError: pass
                    break
            except OSError:
                break
        p.wait()
        os.close(master)
        if master2 is not None: os.close(master2)
        return p.returncode, out, b""
    else:
        # stderr maybe slave tty; if so, need read master async - simplify use communicate if both pipes
        out2,err2=p.communicate()
        err=b""
        if stderr_tty:
            try:
                while True:
                    d=os.read(master,65536)
                    if not d: break
                    err+=d
            except OSError: pass
            os.close(master)
        else:
            err=err2; os.close(master)
        if master2 is not None: os.close(master2)
        return p.returncode,out2,err
if __name__=="__main__":
    # test default size combos
    for cols,rows in [(80,24),(100,40),(10,10),(81,25)]:
        code,out,_=run_pty(["/tmp/half.png"],cols,rows)
        lines=out.decode(errors='replace').splitlines()
        print("term",cols,rows,"code",code,"lines",len(lines),"widths",[len(x) for x in lines[:2]])
    for args in [["/tmp/half.png","-f"],["/tmp/half.png","-W","0"],["/tmp/bw2.png"],["/tmp/grad4.png"]]:
        for cols,rows in [(80,24),(100,40)]:
            code,out,_=run_pty(args,cols,rows)
            lines=out.decode(errors='replace').splitlines()
            print(args,"term",cols,rows,"code",code,"lines",len(lines),"widths",[len(x) for x in lines[:2]])
