import subprocess, glob, os, re
def dims_out(path,args):
    p=subprocess.run(["./executable",path]+args,capture_output=True,text=True)
    lines=p.stdout.splitlines()
    if p.returncode!=0 or (lines and lines[0].startswith("Error")):
        return p.stdout.strip()[:100], p.returncode, p.stderr[:100]
    widths=[len(x) for x in lines]
    return (widths[0] if widths else 0, len(lines)),p.returncode,""
for f in sorted(glob.glob("/tmp/sizes/*.png")):
    for args in [["-W","10"],["-W","7"],["-W","1"],["-W","3"],["-H","10"],["-H","7"],["-H","1"],["-H","3"]]:
        print(os.path.basename(f),args, dims_out(f,args))
