# use model from earlier horizontal then vertical u8
import math
def sinc(x): return 1 if x==0 else math.sin(math.pi*x)/(math.pi*x)
def K(x):
    x=abs(x); return sinc(x)*sinc(x/3) if x<3 else 0
def weights(inn,outn,j):
    scale=inn/outn; center=(j+0.5)*scale-0.5; fs=scale if scale>1 else 1
    ws=[K((i-center)/fs) for i in range(inn)]
    s=sum(ws); return [w/s for w in ws]
def clamp(v): return min(255,max(0,int(round(v))))
def resize(img,ow,oh):
    # img rows RGB tuples; horiz then vert u8
    ih=len(img); iw=len(img[0])
    tmp=[]
    for y in range(ih):
        row=[]
        for x in range(ow):
            ws=weights(iw,ow,x)
            row.append(tuple(clamp(sum(ws[xx]*img[y][xx][c] for xx in range(iw))) for c in range(3)))
        tmp.append(row)
    out=[]
    for y in range(oh):
        ws=weights(ih,oh,y); row=[]
        for x in range(ow): row.append(tuple(clamp(sum(ws[yy]*tmp[yy][x][c] for yy in range(ih))) for c in range(3)))
        out.append(row)
    return out
img=[[(255,0,0),(0,255,0)],[(0,0,255),(255,255,255)]]
r=resize(img,4,8)
for row in r: print(row)
print("checker8 resized 8x8 (for dims4,2 => 8x8)")
chk=[[(255,255,255) if (x+y)%2 else (0,0,0) for x in range(8)] for y in range(8)]
# note checker8 generated (x+y)%2 white if odd
for row in resize(chk,8,8): print([c[0] for c in row])
