{"command":"cat > /tmp/sim_dither.py <<'PY'
import subprocess,struct,zlib
# original pattern for 16x16 constant
bits={(0,0):1,(1,0):8,(0,1):2,(1,1):16,(0,2):4,(1,2):32,(0,3):64,(1,3):128}
def orig(v):
    def chunk(t,data): return struct.pack(">I",len(data))+t+data+struct.pack(">I",zlib.crc32(t+data)&0xffffffff)
    raw=(b"\x00"+bytes([v,v,v])*16)*16
    ihdr=struct.pack(">IIBBBBB",16,16,8,2,0,0,0)
    open("/tmp/gray_const.png","wb").write(b"\x89PNG\r\n\x1a\n"+chunk(b"IHDR",ihdr)+chunk(b"IDAT",zlib.compress(raw))+chunk(b"IEND",b""))
    out=subprocess.check_output(["./executable","/tmp/gray_const.png","-d","8,4","-b","--dither"]).decode().splitlines()
    grid=[[0]*16 for _ in range(16)]
    for cy,line in enumerate(out):
        for cx,ch in enumerate(line):
            val=ord(ch)-0x2800
            for (dx,dy),b in bits.items(): grid[cy*4+dy][cx*2+dx]=1 if val&b else 0
    return grid
def lin(v):
    x=v/255
    return x/12.92 if x<=0.04045 else ((x+0.055)/1.055)**2.4
def sim(v, clamp_mode="add", serpentine=False, threshold_cmp=">"):
    a=[[lin(v) for _ in range(16)] for __ in range(16)]
    out=[[0]*16 for _ in range(16)]
    for y in range(16):
        xs=range(16)
        direction=1
        if serpentine and y%2==1:
            xs=range(15,-1,-1); direction=-1
        for x in xs:
            old=a[y][x]
            if clamp_mode=="quantize": old=min(1,max(0,old))
            new=1 if (old>0.5 if threshold_cmp==">" else old>=0.5) else 0
            out[y][x]=new
            err=old-new
            neigh=[(x+direction,y,7/16),(x-direction,y+1,3/16),(x,y+1,5/16),(x+direction,y+1,1/16)]
            for nx,ny,w in neigh:
                if 0<=nx<16 and 0<=ny<16:
                    a[ny][nx]+=err*w
                    if clamp_mode=="add": a[ny][nx]=min(1,max(0,a[ny][nx]))
    return out
def score(A,B):
    return sum(A[y][x]!=B[y][x] for y in range(16) for x in range(16))
for v in [64,96,128,160,192,224]:
    o=orig(v)
    print("\nVAL",v,"count",sum(sum(r) for r in o))
    for cm in ["none","add","quantize"]:
        for serp in [False,True]:
            s=sim(v,cm,serp)
            print(cm,"serp" if serp else "norm","diff",score(o,s),"cnt",sum(sum(r) for r in s))
PY
python3 /tmp/sim_dither.py
"}

