pal=[]
pal.append((0,(0,0,0)))
bright=[(9,(255,0,0)),(10,(0,255,0)),(11,(255,255,0)),(12,(0,0,255)),(13,(255,0,255)),(14,(0,255,255)),(15,(255,255,255))]
pal+=bright
levels=[0,95,135,175,215,255]
cubeidx={}
for ri,rv in enumerate(levels):
 for gi,gv in enumerate(levels):
  for bi,bv in enumerate(levels):
   idx=16+36*ri+6*gi+bi;c=(rv,gv,bv);cubeidx[c]=idx
for c,idx in cubeidx.items():
 if c not in [x[1] for x in pal]: pal.append((idx,c))
def lin(c):
 x=c/255
 return x/12.92 if x<=0.04045 else ((x+0.055)/1.055)**2.4
def lab(rgb):
 r,g,b=[lin(c) for c in rgb]
 x=r*0.4124+g*0.3576+b*0.1805
 y=r*0.2126+g*0.7152+b*0.0722
 z=r*0.0193+g*0.1192+b*0.9505
 x/=0.95047; y/=1.0; z/=1.08883
 def f(t): return t**(1/3) if t>0.008856 else 7.787*t+16/116
 fx,fy,fz=f(x),f(y),f(z)
 return (116*fy-16,500*(fx-fy),200*(fy-fz))
def nearest(rgb,mode):
 best=None;bi=None
 for idx,c in pal:
  if mode=='rgb': d=sum((a-b)**2 for a,b in zip(rgb,c))
  elif mode=='lin': d=sum((lin(a)-lin(b))**2 for a,b in zip(rgb,c))
  elif mode=='lab':
   l1=lab(rgb);l2=lab(c);d=sum((a-b)**2 for a,b in zip(l1,l2))
  elif mode=='redmean':
   rm=(rgb[0]+c[0])/2;d=(2+rm/256)*(rgb[0]-c[0])**2+4*(rgb[1]-c[1])**2+(2+(255-rm)/256)*(rgb[2]-c[2])**2
  if best is None or d<best: best=d;bi=idx
 return bi
for mode in ['rgb','lin','lab','redmean']:
 diffs=[(c,o,nearest(c,mode)) for c,o in zip(cols,orig) if nearest(c,mode)!=o]
