package main

import (
	"fmt"
	"strings"
)

func runRoot(opts *options, args []string) {
	if len(args) == 0 && !opts.Formats {
		fmt.Print("Error: Need at least 1 input path/url or piped input\nUse the -h flag for more info\n\n")
		return
	}

	hasGif := false
	hasOther := false
	for _, arg := range args {
		if strings.HasSuffix(arg, ".gif") {
			hasGif = true
		} else {
			hasOther = true
		}
	}
	if hasGif && hasOther {
		fmt.Print("Error: There are other inputs along with GIFs\nDue to the potential looping nature of GIFs, non-GIFs must not be supplied alongside\n\n")
		return
	}

	if opts.Formats {
		fmt.Print(formatsOutput)
		return
	}

	for _, arg := range args {
		if arg == "-" && len(args) > 1 {
			fmt.Print("Error: You cannot pass in piped input alongside other inputs\n\n")
			return
		}
	}

	if msg := validateOptions(opts); msg != "" {
		fmt.Print(msg)
		return
	}

	for _, path := range args {
		if processInput(path, opts) {
			return
		}
	}
}

func validateOptions(opts *options) string {
	if len(opts.Map) == 1 {
		return "Need at least 2 characters for --map flag\n\n"
	}
	if len(opts.Dimensions) != 0 {
		if len(opts.Dimensions) != 2 {
			return fmt.Sprintf("Error: requires 2 dimensions, got %d\n\n", len(opts.Dimensions))
		}
		if opts.Dimensions[0] <= 0 || opts.Dimensions[1] <= 0 {
			return "Error: invalid values for dimensions\n\n"
		}
	}
	if opts.Width != 0 && opts.Height != 0 {
		return "Error: both --width and --height can't be set. Use --dimensions instead\n\n"
	}
	if opts.Width < 0 {
		return "Error: invalid value for width\n\n"
	}
	if opts.Height < 0 {
		return "Error: invalid value for height\n\n"
	}
	if len(opts.SaveBG) != 0 {
		if len(opts.SaveBG) != 4 {
			return fmt.Sprintf("Error: --save-bg requires 4 values for RGBA, got %d\n\n", len(opts.SaveBG))
		}
		if !rgbInRange(opts.SaveBG[:3]) || opts.SaveBG[3] < 0 || opts.SaveBG[3] > 100 {
			return "Error: RBG values must be between 0 and 255\nError: Opacity value must be between 0 and 100\n\n"
		}
	}
	if len(opts.FontColor) != 0 {
		if len(opts.FontColor) != 3 {
			return fmt.Sprintf("Error: --font-color requires 3 values for RGB, got %d\n\n", len(opts.FontColor))
		}
		if !rgbInRange(opts.FontColor) {
			return "Error: RBG values must be between 0 and 255\n\n"
		}
	}
	if opts.Threshold < 0 || opts.Threshold > 255 {
		return "Error: threshold must be between 0 and 255\n\n"
	}
	if opts.Dither && !opts.Braille {
		return "Error: image dithering is only reserved for --braille flag\n\n"
	}
	if opts.OnlySave && opts.SaveImg == "" && opts.SaveTxt == "" && opts.SaveGif == "" {
		return "Error: you need to supply one of --save-img, --save-txt or --save-gif for using --only-save\n\n"
	}
	return ""
}

func rgbInRange(v []int) bool {
	for _, c := range v {
		if c < 0 || c > 255 {
			return false
		}
	}
	return true
}

// printConversionError prints a per-input conversion error in the form used
// by the reference: one newline for --only-save and a blank line after it
// for ordinary terminal display.
func printConversionError(opts *options, err error) {
	fmt.Printf("Error: %v\n", err)
	if !opts.OnlySave {
		fmt.Println()
	}
}

// printSaveError prints a save error (always with a trailing blank line) and
// reports through the return value of processInput that processing stops.
func printSaveError(err error) {
	fmt.Printf("Error: can't save file: %v\n\n", err)
}
