package main

import (
	"os"
	"strings"
	"syscall"
	"unsafe"
)

type winsize struct {
	Rows uint16
	Cols uint16
	X    uint16
	Y    uint16
}

func terminalSizeFD(fd uintptr) (int, int, bool) {
	ws := winsize{}
	const tiocgwinsz = 0x5413
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, tiocgwinsz, uintptr(unsafe.Pointer(&ws)))
	if errno != 0 {
		return 0, 0, false
	}
	return int(ws.Cols), int(ws.Rows), true
}

// terminalSize tries stdout first and stdin second, mirroring observed
// behaviour when one of them is redirected to a pipe.
func terminalSize() (int, int, bool) {
	if w, h, ok := terminalSizeFD(os.Stdout.Fd()); ok {
		return w, h, true
	}
	return terminalSizeFD(os.Stdin.Fd())
}

func isInputFromPipe() bool {
	info, _ := os.Stdin.Stat()
	// Deliberately do not hide a nil FileInfo when stdin is closed: the
	// reference crashes in that situation as well.
	return info.Mode()&os.ModeCharDevice == 0
}

type colorProfile int

const (
	profileNone colorProfile = iota
	profileANSI256
	profileTrueColor
)

func detectColorProfile() colorProfile {
	if ct := os.Getenv("COLORTERM"); ct != "" {
		if ct == "truecolor" || ct == "24bit" {
			if os.Getenv("TERM") == "screen" {
				return profileANSI256
			}
			return profileTrueColor
		}
		return profileNone
	}
	if os.Getenv("FORCE_COLOR") != "" {
		return profileNone
	}
	switch os.Getenv("TERM_PROGRAM") {
	case "Hyper":
		return profileTrueColor
	case "iTerm.app", "Apple_Terminal":
		return profileANSI256
	}
	term := os.Getenv("TERM")
	if term == "screen" || strings.Contains(term, "256color") || strings.Contains(term, "xterm") {
		return profileANSI256
	}
	return profileNone
}

func rgbToANSI256(r, g, b uint8) int {
	to6 := func(v uint8) int {
		if v < 48 {
			return 0
		}
		if v < 115 {
			return 1
		}
		return (int(v) - 35) / 40
	}
	idx := 16 + 36*to6(r) + 6*to6(g) + to6(b)
	switch idx {
	case 16:
		return 0
	case 196:
		return 9
	case 46:
		return 10
	case 226:
		return 11
	case 21:
		return 12
	case 201:
		return 13
	case 51:
		return 14
	case 231:
		return 15
	default:
		return idx
	}
}
