package main

func calcHeightFromWidth(width, imgW, imgH int) int {
	return width * imgH / imgW / 2
}

func calcWidthFromHeight(height, imgW, imgH int) int {
	return height * imgW / imgH * 2
}

// calculateDimensions returns an empty slice when terminal dimensions are
// needed but unavailable. The conversion functions index into the result,
// causing the same style of panic as the reference in that situation.
func calculateDimensions(opts *options, imgW, imgH int) []int {
	if opts.Full {
		termW, _, ok := terminalSize()
		if !ok || termW <= 1 {
			return []int{}
		}
		w := termW - 1
		return []int{w, calcHeightFromWidth(w, imgW, imgH)}
	}
	if len(opts.Dimensions) == 2 {
		return []int{opts.Dimensions[0], opts.Dimensions[1]}
	}
	if opts.Width != 0 {
		return []int{opts.Width, calcHeightFromWidth(opts.Width, imgW, imgH)}
	}
	if opts.Height != 0 {
		return []int{calcWidthFromHeight(opts.Height, imgW, imgH), opts.Height}
	}
	termW, termH, ok := terminalSize()
	if !ok || termW <= 1 || termH <= 1 {
		return []int{}
	}
	h := termH - 1
	w := calcWidthFromHeight(h, imgW, imgH)
	if w >= termW {
		w = termW - 1
		h = calcHeightFromWidth(w, imgW, imgH)
	}
	return []int{w, h}
}

func clampDim(v int) int {
	if v < 1 {
		return 1
	}
	return v
}
