package main

import (
	"image"
	"image/color"
	"math"
)

// Pixel stores alpha-premultiplied channel values at the grid's scale
// (255 for 8-bit images, 65535 for 16-bit images).
type Pixel struct {
	R, G, B, A uint32
}

type pixelGrid struct {
	W, H int
	Pix  []Pixel
	Max  uint32
}

func (g *pixelGrid) At(x, y int) Pixel {
	return g.Pix[y*g.W+x]
}

func is16BitImage(img image.Image) bool {
	switch img.(type) {
	case *image.Gray16, *image.RGBA64, *image.NRGBA64, *image.Alpha16:
		return true
	default:
		return false
	}
}

// imageToPixelGrid converts an image to premultiplied pixels. Non-premultiplied
// 8/16-bit images are premultiplied with integer division by the channel
// maximum, matching the values seen from the reference for alpha images.
func imageToPixelGrid(img image.Image) *pixelGrid {
	b := img.Bounds()
	w, h := b.Dx(), b.Dy()
	max := uint32(255)
	if is16BitImage(img) {
		max = 65535
	}
	g := &pixelGrid{W: w, H: h, Pix: make([]Pixel, w*h), Max: max}

	switch src := img.(type) {
	case *image.NRGBA:
		for y := 0; y < h; y++ {
			for x := 0; x < w; x++ {
				c := src.NRGBAAt(b.Min.X+x, b.Min.Y+y)
