				for _, c := range coeffs[y] {
					p := cur.Pix[c.idx*cur.W+x]
					sr += c.w * float64(p.R)
					sg += c.w * float64(p.G)
					sb += c.w * float64(p.B)
					sa += c.w * float64(p.A)
