type artGrid [][]Cell

const defaultCharset = " .:-=+*#%@"
const complexCharset = " .'`^\",:;Il!i><~+_-?][}{1)(|\\/tfjrxnuvczXYUJCLQ0OZmwqpdbkhao*#MW&8%B@$"

func splitCharset(s string) []string {
	out := make([]string, 0, len(s))
	for _, r := range s {
		out = append(out, string(r))
	}
	return out
}

// customCharset mirrors the reference's rune/byte-index behaviour for
// non-ASCII custom maps.
func customCharset(s string) []string {
	out := make([]string, len([]rune(s)))
	for i, r := range s {
		if i < len(out) {
			out[i] = string(r)
		}
	}
	return out
}

func getCharset(opts *options) []string {
	var set []string
	if opts.Map != "" {
		set = customCharset(opts.Map)
	} else if opts.Complex {
		set = splitCharset(complexCharset)
	} else {
		set = splitCharset(defaultCharset)
	}
	if opts.Negative {
		for i, j := 0, len(set)-1; i < j; i, j = i+1, j-1 {
			set[i], set[j] = set[j], set[i]
		}
	}
	return set
}

func applyFlips(x, y, w, h int, opts *options) (int, int) {
	if opts.FlipX {
		x = w - 1 - x
	}
	if opts.FlipY {
		y = h - 1 - y
	}
	return x, y
}

