	set := getCharset(opts)
	art := make(artGrid, h)
	for y := 0; y < h; y++ {
		row := make([]Cell, w)
		for x := 0; x < w; x++ {
			sx, sy := applyFlips(x, y, w, h, opts)
			p := resized.At(sx, sy)
			gray := p.Gray(resized.Max)
			idx := int(gray) * len(set) / 255
			if idx >= len(set) {
				idx = len(set) - 1
			}
