func delinearize(c float64) float64 {
	if c <= 0.04045 {
		return c / 12.92
	}
	return math.Pow((c+0.055)/1.055, 2.4)
}

func clamp01(c float64) float64 {
	if c < 0 {
		return 0
	}
	if c > 1 {
		return 1
	}
	return c
}

// ditherMask applies Floyd-Steinberg error diffusion in linear RGB to a
// black/white palette, clamping colour components after every addition.
func ditherMask(g *pixelGrid) [][]bool {
	type rgb [3]float64
