	for y := range out {
		out[y] = make([]bool, g.W)
	}
	neighbours := []struct {
		dx, dy int
		w      float64
	}{{1, 0, 7.0 / 16}, {-1, 1, 3.0 / 16}, {0, 1, 5.0 / 16}, {1, 1, 1.0 / 16}}
