			distWhite := (1-old[0])*(1-old[0]) + (1-old[1])*(1-old[1]) + (1-old[2])*(1-old[2])
			newV := 0.0
			if distWhite < distBlack {
				newV = 1
				out[y][x] = true
			}
			err := rgb{old[0] - newV, old[1] - newV, old[2] - newV}
			for _, n := range neighbours {
				nx, ny := x+n.dx, y+n.dy
				if nx < 0 || nx >= g.W || ny < 0 || ny >= g.H {
