func fontColorIsSet(opts *options) bool {
	if len(opts.FontColor) != 3 {
		return false
	}
	return !(opts.FontColor[0] == 255 && opts.FontColor[1] == 255 && opts.FontColor[2] == 255)
}

func effectiveFontColor(opts *options) (uint8, uint8, uint8) {
	if len(opts.FontColor) == 3 {
		return uint8(opts.FontColor[0]), uint8(opts.FontColor[1]), uint8(opts.FontColor[2])
	}
	return 255, 255, 255
}

