		return 1
	}
	return c
}

// ditherMask applies Floyd-Steinberg error diffusion in linear RGB to a
// black/white palette, clamping colour components after every addition.
func ditherMask(g *pixelGrid) [][]bool {
	type rgb [3]float64
	vals := make([][]rgb, g.H)
	for y := 0; y < g.H; y++ {
		vals[y] = make([]rgb, g.W)
		for x := 0; x < g.W; x++ {
			r, gg, b := g.At(x, y).rawRGBFloat(g.Max)
			vals[y][x] = rgb{delinearize(r), delinearize(gg), delinearize(b)}
		}
	}
	out := make([][]bool, g.H)
	for y := range out {
		out[y] = make([]bool, g.W)
	}
	neighbours := []struct {
		dx, dy int
		w      float64
	}{{1, 0, 7.0 / 16}, {-1, 1, 3.0 / 16}, {0, 1, 5.0 / 16}, {1, 1, 1.0 / 16}}
	for y := 0; y < g.H; y++ {
		for x := 0; x < g.W; x++ {
			old := vals[y][x]
			distBlack := old[0]*old[0] + old[1]*old[1] + old[2]*old[2]
			distWhite := (1-old[0])*(1-old[0]) + (1-old[1])*(1-old[1]) + (1-old[2])*(1-old[2])
			newV := 0.0
			if distWhite < distBlack {
				newV = 1
				out[y][x] = true
			}
			err := rgb{old[0] - newV, old[1] - newV, old[2] - newV}
			for _, n := range neighbours {
				nx, ny := x+n.dx, y+n.dy
				if nx < 0 || nx >= g.W || ny < 0 || ny >= g.H {
					continue
				}
				for i := 0; i < 3; i++ {
					vals[ny][nx][i] = clamp01(vals[ny][nx][i] + err[i]*n.w)
				}
			}
		}
	}
	return out
}

func convertToBraille(src *pixelGrid, dimensions []int, opts *options) artGrid {
	_ = dimensions[0]
	_ = dimensions[1]
	w := clampDim(dimensions[0])
	h := clampDim(dimensions[1])
	resized := resizePixelGrid(src, w*2, h*4)
	threshold := opts.Threshold
	if threshold == 0 {
		threshold = 128
	}
	var mask [][]bool
	if opts.Dither {
		mask = ditherMask(resized)
	}
	dotBits := [2][4]rune{{1, 2, 4, 0x40}, {8, 0x10, 0x20, 0x80}}
	art := make(artGrid, h)
	for cy := 0; cy < h; cy++ {
		row := make([]Cell, w)
		for cx := 0; cx < w; cx++ {
			bits := rune(0)
			var colorP Pixel
			for dy := 0; dy < 4; dy++ {
				for dx := 0; dx < 2; dx++ {
					ox, oy := cx*2+dx, cy*4+dy
					sx, sy := applyFlips(ox, oy, w*2, h*4, opts)
					p := resized.At(sx, sy)
					if dx == 0 && dy == 0 {
						colorP = p
					}
					on := false
					if opts.Dither {
						on = mask[sy][sx]
						if opts.Negative {
							on = !on
						}
					} else {
						gray := p.Gray(resized.Max)
						if opts.Negative {
							on = int(gray) <= threshold
						} else {
							on = int(gray) >= threshold
						}
					}
					if on {
						bits |= dotBits[dx][dy]
					}
				}
			}
			r, g, b := colorP.RGB8(resized.Max)
			row[cx] = Cell{Str: string(rune(0x2800 + bits)), R: r, G: g, B: b, Gray: colorP.Gray(resized.Max)}
		}
		art[cy] = row
	}
	return art
}

func (a artGrid) plainLines() []string {
	lines := make([]string, len(a))
	for y, row := range a {
		var sb strings.Builder
		for _, c := range row {
			sb.WriteString(c.Str)
		}
		lines[y] = sb.String()
	}
	return lines
}

func fontColorIsSet(opts *options) bool {
	if len(opts.FontColor) != 3 {
		return false
	}
	return !(opts.FontColor[0] == 255 && opts.FontColor[1] == 255 && opts.FontColor[2] == 255)
}

func effectiveFontColor(opts *options) (uint8, uint8, uint8) {
	if len(opts.FontColor) == 3 {
		return uint8(opts.FontColor[0]), uint8(opts.FontColor[1]), uint8(opts.FontColor[2])
	}
	return 255, 255, 255
}

func cellRGB(c Cell, opts *options) (uint8, uint8, uint8) {
	if opts.Color {
		if opts.Negative {
			return 255 - c.R, 255 - c.G, 255 - c.B
		}
		return c.R, c.G, c.B
	}
	if opts.Grayscale {
		g := c.Gray
		if opts.Negative {
			g = 255 - g
		}
		return g, g, g
	}
	return effectiveFontColor(opts)
}

// renderColored validates terminal colour support (if colouring was
// requested) and returns terminal-ready lines.
func renderColored(art artGrid, opts *options) ([]string, error) {
	if !(opts.Color || opts.Grayscale || fontColorIsSet(opts)) {
		return art.plainLines(), nil
	}
	profile := detectColorProfile()
	if profile == profileNone {
		return nil, fmt.Errorf("your terminal supports neither 24-bit nor 8-bit colors. Other coloring options aren't available")
	}
	if os.Getenv("NO_COLOR") != "" {
		return art.plainLines(), nil
	}
	code := "38"
	if opts.ColorBG {
		code = "48"
	}
	lines := make([]string, len(art))
	for y, row := range art {
		var sb strings.Builder
		for _, c := range row {
			r, g, b := cellRGB(c, opts)
			if profile == profileTrueColor {
				fmt.Fprintf(&sb, "\x1b[%s;2;%d;%d;%dm%s\x1b[0m", code, r, g, b, c.Str)
			} else {
				fmt.Fprintf(&sb, "\x1b[%s;5;%dm%s\x1b[0m", code, rgbToANSI256(r, g, b), c.Str)
			}
		}
		lines[y] = sb.String()
	}
	return lines, nil
}

// validateColorSupportOnly is used before any saving is attempted.
func validateColorSupportOnly(opts *options) error {
	if !(opts.Color || opts.Grayscale || fontColorIsSet(opts)) {
		return nil
	}
	if detectColorProfile() == profileNone {
		return fmt.Errorf("your terminal supports neither 24-bit nor 8-bit colors. Other coloring options aren't available")
	}
	return nil
}
