package main

import (
	"bytes"
	"fmt"
	"image"
	"image/gif"
	"io"
	"net/http"
	"os"
	"strings"
	"time"

	_ "image/jpeg"
	_ "image/png"
)

func isURL(path string) bool {
	return len(path) > 7 && (strings.HasPrefix(path, "http://") || strings.HasPrefix(path, "https://"))
}

func isGifPath(path string) bool {
	return strings.HasSuffix(path, ".gif")
}

// processInput returns true when the whole run should stop.
func processInput(path string, opts *options) bool {
	if path == "-" {
		return processPiped(opts)
	}
	if isURL(path) {
		return processURL(path, opts)
	}
	if isGifPath(path) {
		return processGifFile(path, opts)
	}
	return processStillFile(path, opts)
}

func processStillFile(path string, opts *options) bool {
	f, err := os.Open(path)
	if err != nil {
		printConversionError(opts, fmt.Errorf("unable to open file: %v", err))
		return false
	}
	defer f.Close()
	font, err := loadFontIfRequested(opts)
	if err != nil {
		printConversionError(opts, err)
		return false
	}
	img, _, err := image.Decode(f)
	if err != nil {
		printConversionError(opts, fmt.Errorf("can't decode %s: %v", path, err))
		return false
	}
	return processStillDecoded(img, path, opts, font)
}

func processGifFile(path string, opts *options) bool {
	f, err := os.Open(path)
	if err != nil {
		printConversionError(opts, fmt.Errorf("unable to open file: %v", err))
		return false
	}
	defer f.Close()
	font, err := loadFontIfRequested(opts)
	if err != nil {
		printConversionError(opts, err)
		return false
	}
	g, err := gif.DecodeAll(f)
	if err != nil {
		printConversionError(opts, fmt.Errorf("can't decode %s: %v", path, err))
		return false
	}
	return processGifDecoded(g, path, opts, font)
}

func fetchURL(path string, opts *options) ([]byte, bool) {
	fmt.Print("Fetching file from url...\r")
	resp, err := http.Get(path)
	if err != nil {
		printConversionError(opts, fmt.Errorf("can't fetch content: %v", err))
		return nil, true
	}
	defer resp.Body.Close()
	data, err := io.ReadAll(resp.Body)
	if err != nil {
		printConversionError(opts, fmt.Errorf("can't fetch content: %v", err))
		return nil, true
	}
	fmt.Print("                          \r")
	return data, false
}

func processURL(path string, opts *options) bool {
	data, stop := fetchURL(path, opts)
	if stop {
		return false
	}
	font, err := loadFontIfRequested(opts)
	if err != nil {
		printConversionError(opts, err)
		return false
	}
