package main

import (
	"fmt"
	"image"
	"image/color/palette"
	"image/draw"
	"image/gif"
	"os"
)

func gifFrameCanvasSize(cols, rows, origW, origH int) (int, int, float64, float64) {
	var cellW float64
	if cols > 2*rows {
		cellW = float64(origH) / float64(rows) / 2
	} else {
		cellW = float64(origW) / float64(cols)
	}
	cellH := cellW * 2
	w := int(10 + float64(cols)*cellW)
	h := int(10 + float64(rows)*cellH)
	return w, h, cellW, cellH
}

func saveArtGif(arts []artGrid, src *gif.GIF, input string, opts *options, font *loadedFont) error {
	dir := normalizedSaveDir(opts.SaveGif)
	if _, err := os.Stat(dir); err != nil {
		return err
	}
	origW, origH := 0, 0
	if len(src.Image) > 0 {
		b := src.Image[0].Bounds()
		origW, origH = b.Dx(), b.Dy()
	}
	out := &gif.GIF{LoopCount: src.LoopCount}
	fmt.Print("Saving gif... 0%\r")
	for i, art := range arts {
		cols := 0
		if len(art) > 0 {
			cols = len(art[0])
		}
		tw, th, _, _ := gifFrameCanvasSize(cols, len(art), origW, origH)
		rendered := renderArtImage(art, opts, font, tw, th)
		paletted := image.NewPaletted(rendered.Bounds(), palette.Plan9)
		draw.FloydSteinberg.Draw(paletted, rendered.Bounds(), rendered, image.Point{})
		out.Image = append(out.Image, paletted)
		delay := 0
		if i < len(src.Delay) {
			delay = src.Delay[i]
		}
		out.Delay = append(out.Delay, delay)
		fmt.Printf("Saving gif... %d%%\r", (i+1)*100/len(arts))
	}
	dest := dir + inputBaseName(input, true) + "-ascii-art.gif"
	f, err := os.Create(dest)
	if err != nil {
		return err
	}
	defer f.Close()
	if err := gif.EncodeAll(f, out); err != nil {
		return err
	}
	fmt.Printf("                     \rSaved %s\n", dest)
	return nil
}
