// Package bmp implements a small BMP decoder compatible with the subset
// accepted by the decoder used by the reference executable: uncompressed
// 8-bit (256-entry palette), 24-bit and 32-bit images with 40, 108 or
// 124-byte DIB headers.
package bmp

import (
	"bufio"
	"encoding/binary"
	"errors"
	"image"
	"image/color"
	"io"
)

var errUnsupported = errors.New("bmp: unsupported BMP image")

func init() {
	image.RegisterFormat("bmp", "BM????\x00\x00\x00\x00", Decode, DecodeConfig)
}

type header struct {
	off           uint32
	dibSize       uint32
	width, height int32
	planes, bpp   uint16
	compression   uint32
}

func readHeader(r io.Reader) (*header, *bufio.Reader, error) {
	br, ok := r.(*bufio.Reader)
	if !ok {
		br = bufio.NewReader(r)
	}
	var fh [14]byte
	if _, err := io.ReadFull(br, fh[:]); err != nil {
		return nil, br, err
	}
	if fh[0] != 'B' || fh[1] != 'M' {
		return nil, br, image.ErrFormat
	}
	h := &header{off: binary.LittleEndian.Uint32(fh[10:14])}
	var dibSizeB [4]byte
	if _, err := io.ReadFull(br, dibSizeB[:]); err != nil {
		return nil, br, err
	}
	h.dibSize = binary.LittleEndian.Uint32(dibSizeB[:])
	if h.dibSize != 40 && h.dibSize != 108 && h.dibSize != 124 {
		return nil, br, errUnsupported
	}
	rest := make([]byte, int(h.dibSize)-4)
	if _, err := io.ReadFull(br, rest); err != nil {
		return nil, br, err
	}
	h.width = int32(binary.LittleEndian.Uint32(rest[0:4]))
	h.height = int32(binary.LittleEndian.Uint32(rest[4:8]))
	h.planes = binary.LittleEndian.Uint16(rest[8:10])
	h.bpp = binary.LittleEndian.Uint16(rest[10:12])
	h.compression = binary.LittleEndian.Uint32(rest[12:16])
	if h.planes != 1 || h.compression != 0 {
		return nil, br, errUnsupported
	}
	if h.width < 0 {
		return nil, br, errUnsupported
	}
	switch h.bpp {
	case 8, 24, 32:
	default:
		return nil, br, errUnsupported
	}
	expectedOff := uint32(14) + h.dibSize
	if h.bpp == 8 {
		expectedOff += 256 * 4
	}
	if h.off != expectedOff {
		return nil, br, errUnsupported
	}
	return h, br, nil
}

func DecodeConfig(r io.Reader) (image.Config, error) {
	h, _, err := readHeader(r)
	if err != nil {
		return image.Config{}, err
	}
	height := h.height
	if height < 0 {
		height = -height
	}
	model := color.RGBAModel
	if h.bpp == 32 {
		model = color.NRGBAModel
	}
	return image.Config{ColorModel: model, Width: int(h.width), Height: int(height)}, nil
}

func Decode(r io.Reader) (image.Image, error) {
	h, br, err := readHeader(r)
	if err != nil {
		return nil, err
	}

	var palette [256]color.RGBA
	if h.bpp == 8 {
		var palBytes [256 * 4]byte
		if _, err := io.ReadFull(br, palBytes[:]); err != nil {
			return nil, err
		}
		for i := 0; i < 256; i++ {
			palette[i] = color.RGBA{palBytes[i*4+2], palBytes[i*4+1], palBytes[i*4+0], 255}
		}
	}

	width := int(h.width)
	height64 := int64(h.height)
	topDown := height64 < 0
	if topDown {
		height64 = -height64
	}
	height := int(height64)

	// The reference decoder happily creates empty images for zero sizes.
	if width == 0 || height == 0 {
		if h.bpp == 32 {
