// Package tiff implements the baseline TIFF features exercised by this
// program: little/big-endian stripped or tiled images in grey, palette and
// RGB colour, with no compression, PackBits, LZW or zlib/deflate.
package tiff

import (
	"bytes"
	"compress/zlib"
	"encoding/binary"
	"errors"
	"fmt"
	"image"
	"image/color"
	"io"
	"sort"
)

func init() {
	image.RegisterFormat("tiff", "II*\x00", Decode, DecodeConfig)
	image.RegisterFormat("tiff", "MM\x00*", Decode, DecodeConfig)
}

var (
	errColorModel = errors.New("tiff: unsupported feature: color model")
)

func unsupported(format string, args ...interface{}) error {
	return fmt.Errorf("tiff: unsupported feature: "+format, args...)
}
func invalid(format string, args ...interface{}) error {
	return fmt.Errorf("tiff: invalid format: "+format, args...)
}

type entry struct {
	tag   uint16
	typ   uint16
	count uint32
	raw   []byte // value bytes in file byte order
}

type decoder struct {
	data  []byte
	order binary.ByteOrder
	tags  map[uint16]entry
}

var typeSizes = map[uint16]int{1: 1, 2: 1, 3: 2, 4: 4, 5: 8, 6: 1, 7: 1, 8: 2, 9: 4, 10: 8, 11: 4, 12: 8}

func parse(r io.Reader) (*decoder, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}
	if len(data) < 8 {
		return nil, io.ErrUnexpectedEOF
	}
	d := &decoder{data: data, tags: map[uint16]entry{}}
	switch string(data[:2]) {
	case "II":
		d.order = binary.LittleEndian
	case "MM":
		d.order = binary.BigEndian
	default:
		return nil, image.ErrFormat
	}
	if d.order.Uint16(data[2:4]) != 42 {
		return nil, image.ErrFormat
	}
	off := int(d.order.Uint32(data[4:8]))
	if off < 0 || off+2 > len(data) {
		return nil, io.ErrUnexpectedEOF
	}
	n := int(d.order.Uint16(data[off : off+2]))
	off += 2
	if off+n*12 > len(data) {
		return nil, io.ErrUnexpectedEOF
	}
	for i := 0; i < n; i++ {
		eBytes := data[off+i*12 : off+(i+1)*12]
		e := entry{tag: d.order.Uint16(eBytes[0:2]), typ: d.order.Uint16(eBytes[2:4]), count: d.order.Uint32(eBytes[4:8])}
		size, ok := typeSizes[e.typ]
		if !ok {
			continue
		}
		total := int64(e.count) * int64(size)
		if total <= 4 {
			e.raw = append([]byte(nil), eBytes[8:8+total]...)
		} else {
			vOff := int64(d.order.Uint32(eBytes[8:12]))
			if vOff < 0 || vOff+total > int64(len(data)) {
				return nil, io.ErrUnexpectedEOF
			}
			e.raw = append([]byte(nil), data[vOff:vOff+total]...)
		}
		d.tags[e.tag] = e
	}
	return d, nil
}

func (d *decoder) ints(tag uint16) ([]int64, bool) {
	e, ok := d.tags[tag]
	if !ok {
		return nil, false
	}
	out := make([]int64, 0, e.count)
	switch e.typ {
	case 1, 2, 7:
		for _, b := range e.raw {
			out = append(out, int64(b))
		}
	case 6:
		for _, b := range e.raw {
			out = append(out, int64(int8(b)))
		}
	case 3:
		for i := 0; i+1 < len(e.raw); i += 2 {
			out = append(out, int64(d.order.Uint16(e.raw[i:i+2])))
		}
	case 8:
		for i := 0; i+1 < len(e.raw); i += 2 {
			out = append(out, int64(int16(d.order.Uint16(e.raw[i:i+2]))))
		}
	case 4:
		for i := 0; i+3 < len(e.raw); i += 4 {
			out = append(out, int64(d.order.Uint32(e.raw[i:i+4])))
		}
	case 9:
		for i := 0; i+3 < len(e.raw); i += 4 {
			out = append(out, int64(int32(d.order.Uint32(e.raw[i:i+4]))))
		}
	case 5: // rational: expose numerator/denominator pairs as two values (unused here)
		for i := 0; i+7 < len(e.raw); i += 8 {
			out = append(out, int64(d.order.Uint32(e.raw[i:i+4])), int64(d.order.Uint32(e.raw[i+4:i+8])))
		}
	default:
		return nil, false
	}
	return out, true
}

func (d *decoder) int1(tag uint16, def int64) int64 {
	if v, ok := d.ints(tag); ok && len(v) > 0 {
		return v[0]
	}
	return def
}
func (d *decoder) intList(tag uint16, def []int64) []int64 {
	if v, ok := d.ints(tag); ok {
		return v
	}
	return def
}

type info struct {
	w, h       int
	bps        []int64
	comp       int64
	photo      int64
	spp        int64
	planar     int64
	predictor  int64
	fillOrder  int64
	extra      []int64
	sampleFmt  []int64
	colorModel color.Model

	isTiled  bool
	tileW    int
	tileH    int
	offsets  []int64
	counts   []int64
	rowsPS   int64
	numBlocks int
}

func (d *decoder) imageInfo(forConfig bool) (*info, error) {
	inf := &info{}
	inf.w = int(d.int1(256, 0))
	inf.h = int(d.int1(257, 0))
	inf.bps = d.intList(258, []int64{1})
	inf.comp = d.int1(259, 1)
	inf.photo = d.int1(262, 0)
	inf.spp = d.int1(277, 1)
	inf.planar = d.int1(284, 1)
	inf.predictor = d.int1(317, 1)
	inf.fillOrder = d.int1(266, 1)
	inf.extra, _ = d.ints(338)
	inf.sampleFmt = d.intList(339, nil)

	switch inf.comp {
	case 1, 5, 8, 32773, 32946:
	default:
		return nil, unsupported("compression value %d", inf.comp)
	}
	for _, sf := range inf.sampleFmt {
		if sf != 1 {
			return nil, unsupported("sample format")
		}
	}

	// Decide the output colour model / validate relevant combinations.
	switch inf.photo {
	case 0, 1:
		if inf.spp != 1 && inf.spp != 2 {
			return nil, invalid("wrong number of samples for Gray")
		}
	case 2:
		if inf.spp == 4 {
			if len(inf.extra) != 1 || (inf.extra[0] != 1 && inf.extra[0] != 2) {
				return nil, invalid("wrong number of samples for RGB")
			}
		} else if inf.spp != 3 {
			return nil, invalid("wrong number of samples for RGB")
		}
	case 3:
		if inf.spp != 1 {
			return nil, invalid("wrong number of samples for Palette")
		}
	default:
		return nil, errColorModel
	}

	inf.colorModel = outputModel(inf)
	if inf.colorModel == nil {
		return nil, errColorModel
	}
	if forConfig {
		return inf, nil
	}

	// Blocks.
	if _, hasTiles := d.tags[324]; hasTiles {
		inf.isTiled = true
		inf.tileW = int(d.int1(322, 0))
		inf.tileH = int(d.int1(323, 0))
		inf.offsets, _ = d.ints(324)
		inf.counts, _ = d.ints(325)
		if inf.tileW <= 0 || inf.tileH <= 0 {
			return nil, invalid("tile size")
		}
		tilesX := (inf.w + inf.tileW - 1) / inf.tileW
		tilesY := (inf.h + inf.tileH - 1) / inf.tileH
		inf.numBlocks = tilesX * tilesY
		if inf.planar == 2 {
			inf.numBlocks *= int(inf.spp)
		}
	} else {
		inf.offsets, _ = d.ints(273)
		inf.counts, _ = d.ints(279)
		inf.rowsPS = d.int1(278, 1<<31-1)
		if inf.rowsPS <= 0 {
			inf.rowsPS = int64(inf.h)
		}
		rows := int64(inf.h)
		n := int((rows + inf.rowsPS - 1) / inf.rowsPS)
		if inf.planar == 2 {
			n *= int(inf.spp)
		}
		inf.numBlocks = n
	}
	if len(inf.offsets) < inf.numBlocks || len(inf.counts) < inf.numBlocks {
		return nil, invalid("not enough pixel data")
	}
	if inf.planar == 2 && inf.spp > 1 && !inf.isTiled {
		// The reference decoder does not handle separate planar strips.
		return nil, invalid("not enough pixel data")
	}
	return inf, nil
}

func firstBPS(inf *info) int64 {
	if len(inf.bps) > 0 {
		return inf.bps[0]
	}
	return 1
}

func outputModel(inf *info) color.Model {
	bps := firstBPS(inf)
	for _, b := range inf.bps {
		if b != bps {
			return nil
		}
	}
	switch inf.photo {
	case 0, 1:
		if inf.spp == 2 {
			if bps == 16 {
				return color.NRGBA64Model
			}
			if bps == 8 {
				return color.NRGBAModel
			}
			return nil
		}
		switch bps {
		case 1, 2, 4, 8:
			return color.GrayModel
		case 16:
			return color.Gray16Model
		}
	case 2:
		if bps == 8 {
			if inf.spp == 4 {
				return color.NRGBAModel
			}
			return color.RGBAModel
		}
		if bps == 16 {
			if inf.spp == 4 {
				return color.NRGBA64Model
			}
			return color.RGBA64Model
		}
	case 3:
		switch bps {
		case 1, 2, 4, 8, 16:
			return color.RGBAModel
		}
	}
	return nil
}

func DecodeConfig(r io.Reader) (image.Config, error) {
	d, err := parse(r)
	if err != nil {
		return image.Config{}, err
	}
	inf, err := d.imageInfo(true)
	if err != nil {
		return image.Config{}, err
	}
	return image.Config{ColorModel: inf.colorModel, Width: inf.w, Height: inf.h}, nil
}

func decompress(comp int64, in []byte) ([]byte, error) {
	switch comp {
	case 1:
		return append([]byte(nil), in...), nil
	case 32773:
		return decodePackBits(in), nil
	case 5:
		return decodeLZW(in)
	case 8, 32946:
		zr, err := zlib.NewReader(bytes.NewReader(in))
		if err != nil {
			return nil, err
		}
		defer zr.Close()
		return io.ReadAll(zr)
	default:
		return nil, unsupported("compression value %d", comp)
	}
}

func decodePackBits(in []byte) []byte {
	var out []byte
	for i := 0; i < len(in); {
		n := int(int8(in[i]))
		i++
		switch {
		case n >= 0:
			cnt := n + 1
			for k := 0; k < cnt && i < len(in); k++ {
				out = append(out, in[i])
				i++
			}
		case n >= -127:
			if i < len(in) {
				b := in[i]
				i++
				for k := 0; k < -n+1; k++ {
					out = append(out, b)
				}
			}
		default: // -128 no-op
		}
	}
	return out
}

// TIFF LZW (MSB-first, early code-width change).
func decodeLZW(in []byte) ([]byte, error) {
	const clearCode = 256
	const eoiCode = 257
	bitPos := 0
	readCode := func(width int) (int, bool) {
		if bitPos+width > len(in)*8 {
			return 0, false
		}
		v := 0
		for i := 0; i < width; i++ {
			byteIdx := (bitPos + i) / 8
			bit := 7 - uint((bitPos+i)%8)
			v = (v << 1) | int((in[byteIdx]>>bit)&1)
		}
		bitPos += width
		return v, true
	}
	var dictionary [][]byte
	reset := func() {
		dictionary = make([][]byte, 258)
		for i := 0; i < 256; i++ {
			dictionary[i] = []byte{byte(i)}
		}
	}
	reset()
	width := 9
	var prev []byte
	var out []byte
	for {
		code, ok := readCode(width)
		if !ok {
			break
		}
		if code == clearCode {
			reset()
			width = 9
			prev = nil
			continue
		}
		if code == eoiCode {
			break
		}
		var entry []byte
		if code < len(dictionary) && dictionary[code] != nil {
			entry = dictionary[code]
		} else if prev != nil && code == len(dictionary) {
			entry = append(append([]byte(nil), prev...), prev[0])
		} else {
			return out, invalid("LZW code out of range")
		}
		out = append(out, entry...)
		if prev != nil {
			dictionary = append(dictionary, append(append([]byte(nil), prev...), entry[0]))
			// Early change: widen when the next available code no
			// longer fits in the current width.
			if len(dictionary) == (1<<width) && width < 12 {
				width++
			}
		}
		prev = append([]byte(nil), entry...)
	}
	return out, nil
}

func applyPredictor(data []byte, inf *info, blockW, blockH int, order binary.ByteOrder) {
	if inf.predictor != 2 {
		return
	}
	bps := firstBPS(inf)
	samplesPerRow := blockW
	if inf.planar == 1 {
		samplesPerRow = blockW * int(inf.spp)
	}
	strideSamples := int(inf.spp)
	if inf.planar == 2 {
		strideSamples = 1
	}
	switch bps {
	case 8:
		rowBytes := samplesPerRow
		for y := 0; y < blockH; y++ {
			base := y * rowBytes
			if base+rowBytes > len(data) {
				return
			}
			for i := strideSamples; i < samplesPerRow; i++ {
				data[base+i] += data[base+i-strideSamples]
			}
		}
	case 16:
		rowBytes := samplesPerRow * 2
		for y := 0; y < blockH; y++ {
			base := y * rowBytes
			if base+rowBytes > len(data) {
				return
			}
			for i := strideSamples; i < samplesPerRow; i++ {
				cur := order.Uint16(data[base+i*2:])
				prev := order.Uint16(data[base+(i-strideSamples)*2:])
				order.PutUint16(data[base+i*2:], cur+prev)
			}
		}
	}
}

// bitReader reads MSB-first (FillOrder 1) or LSB-first within bytes (2).
type bitReader struct {
	data      []byte
	bytePos   int
	bitPos    uint // bits already consumed in current byte
	fillOrder int64
}

func (b *bitReader) read(bits int) uint32 {
	var v uint32
	for i := 0; i < bits; i++ {
		if b.bytePos >= len(b.data) {
			return v
		}
		cur := b.data[b.bytePos]
		var bit byte
		if b.fillOrder == 2 {
			bit = (cur >> b.bitPos) & 1
		} else {
			bit = (cur >> (7 - b.bitPos)) & 1
		}
		v = (v << 1) | uint32(bit)
		b.bitPos++
		if b.bitPos == 8 {
			b.bitPos = 0
			b.bytePos++
		}
	}
	return v
}
func (b *bitReader) align() {
	if b.bitPos != 0 {
		b.bitPos = 0
		b.bytePos++
	}
}

func Decode(r io.Reader) (image.Image, error) {
	d, err := parse(r)
	if err != nil {
		return nil, err
	}
	inf, err := d.imageInfo(false)
	if err != nil {
		return nil, err
	}
	w, h := inf.w, inf.h
	bps := firstBPS(inf)
	spp := int(inf.spp)

	// Determine destination image.
	var dst image.Image
	var setSample func(x, y int, s []uint32)
	// Palette, if any.
	var cmap []uint16
	if inf.photo == 3 {
		cvals, ok := d.ints(320)
		if !ok {
			return nil, invalid("palette colour map missing")
		}
		for _, v := range cvals {
			cmap = append(cmap, uint16(v))
		}
	}

	switch inf.colorModel {
	case color.GrayModel:
		img := image.NewGray(image.Rect(0, 0, w, h))
		dst = img
		setSample = func(x, y int, s []uint32) {
			v := scaleSample(s[0], bps)
			if inf.photo == 0 {
				v = 255 - v
			}
			img.SetGray(x, y, color.Gray{uint8(v)})
		}
	case color.Gray16Model:
		img := image.NewGray16(image.Rect(0, 0, w, h))
		dst = img
		setSample = func(x, y int, s []uint32) {
			v := uint16(s[0])
			if inf.photo == 0 {
				v = 65535 - v
			}
			img.SetGray16(x, y, color.Gray16{v})
		}
	case color.RGBAModel:
		img := image.NewRGBA(image.Rect(0, 0, w, h))
		dst = img
		if inf.photo == 3 {
			setSample = func(x, y int, s []uint32) {
				idx := int(s[0])
				n := len(cmap) / 3
				var r, g, b uint16
				if idx < n {
					r, g, b = cmap[idx], cmap[n+idx], cmap[2*n+idx]
				}
				img.SetRGBA(x, y, color.RGBA{uint8(r >> 8), uint8(g >> 8), uint8(b >> 8), 255})
			}
		} else {
			setSample = func(x, y int, s []uint32) {
				img.SetRGBA(x, y, color.RGBA{uint8(s[0]), uint8(s[1]), uint8(s[2]), 255})
			}
		}
	case color.RGBA64Model:
		img := image.NewRGBA64(image.Rect(0, 0, w, h))
		dst = img
		setSample = func(x, y int, s []uint32) {
			img.SetRGBA64(x, y, color.RGBA64{uint16(s[0]), uint16(s[1]), uint16(s[2]), 65535})
		}
	case color.NRGBAModel:
		img := image.NewNRGBA(image.Rect(0, 0, w, h))
		dst = img
		setSample = func(x, y int, s []uint32) {
			if inf.photo == 0 || inf.photo == 1 {
				v := uint8(scaleSample(s[0], bps))
				if inf.photo == 0 {
					v = 255 - v
				}
				a := uint8(255)
				if len(s) > 1 {
					a = uint8(scaleSample(s[1], bps))
				}
				img.SetNRGBA(x, y, color.NRGBA{v, v, v, a})
				return
			}
			a := uint8(s[3])
			if len(inf.extra) == 1 && inf.extra[0] == 1 {
				// Associated (premultiplied) alpha: convert through
				// the NRGBA colour model.
				c := color.NRGBAModel.Convert(color.RGBA{uint8(s[0]), uint8(s[1]), uint8(s[2]), a}).(color.NRGBA)
				img.SetNRGBA(x, y, c)
			} else {
				img.SetNRGBA(x, y, color.NRGBA{uint8(s[0]), uint8(s[1]), uint8(s[2]), a})
			}
		}
	case color.NRGBA64Model:
		img := image.NewNRGBA64(image.Rect(0, 0, w, h))
		dst = img
		setSample = func(x, y int, s []uint32) {
			if inf.photo == 0 || inf.photo == 1 {
				v := uint16(s[0])
				if inf.photo == 0 {
					v = 65535 - v
				}
				a := uint16(65535)
				if len(s) > 1 {
					a = uint16(s[1])
				}
				img.SetNRGBA64(x, y, color.NRGBA64{v, v, v, a})
				return
			}
			a := uint16(s[3])
			if len(inf.extra) == 1 && inf.extra[0] == 1 {
				c := color.NRGBA64Model.Convert(color.RGBA64{uint16(s[0]), uint16(s[1]), uint16(s[2]), a}).(color.NRGBA64)
				img.SetNRGBA64(x, y, c)
			} else {
				img.SetNRGBA64(x, y, color.NRGBA64{uint16(s[0]), uint16(s[1]), uint16(s[2]), a})
			}
		}
	default:
		return nil, errColorModel
	}

	// Read blocks in order.
	// Buffer for planar-separate samples.
	type sampleBuf [][]uint32
	var planarBuf sampleBuf
	if inf.planar == 2 {
		planarBuf = make([][]uint32, h)
		for i := range planarBuf {
			planarBuf[i] = make([]uint32, w*spp)
		}
	}

	for block := 0; block < inf.numBlocks; block++ {
		off := inf.offsets[block]
		cnt := inf.counts[block]
		if off < 0 || cnt < 0 || off+cnt > int64(len(d.data)) {
			return nil, io.ErrUnexpectedEOF
		}
		raw, err := decompress(inf.comp, d.data[off:off+cnt])
		if err != nil {
			return nil, err
		}

		// Geometry of this block.
		bx, by, bw, bh := 0, 0, w, h
		plane := 0
		if inf.isTiled {
			tilesX := (w + inf.tileW - 1) / inf.tileW
			perPlane := tilesX * ((h + inf.tileH - 1) / inf.tileH)
			idx := block
			if inf.planar == 2 {
				plane = block / perPlane
				idx = block % perPlane
			}
			bx = (idx % tilesX) * inf.tileW
			by = (idx / tilesX) * inf.tileH
			bw = min(inf.tileW, w-bx)
			bh = min(inf.tileH, h-by)
		} else {
			rowsPerStrip := int(inf.rowsPS)
			perPlane := (h + rowsPerStrip - 1) / rowsPerStrip
			idx := block
			if inf.planar == 2 {
				plane = block / perPlane
				idx = block % perPlane
			}
			by = idx * rowsPerStrip
			bh = min(rowsPerStrip, h-by)
		}

		applyPredictor(raw, inf, bw, bh, d.order)

		// Expected number of sample values in this block.
		samplesInBlock := bw * bh
		if inf.planar == 1 {
			samplesInBlock *= spp
		}
		// Read samples.
		samples, err := readSamples(raw, samplesInBlock, bw, bh, inf, d.order)
		if err != nil {
			return nil, err
		}
		if len(samples) < samplesInBlock {
			return nil, invalid("not enough pixel data")
		}

		if inf.planar == 2 {
			// Store into planar buffer; emit when all planes done.
			si := 0
			for yy := 0; yy < bh; yy++ {
				for xx := 0; xx < bw; xx++ {
					planarBuf[by+yy][(bx+xx)*spp+plane] = samples[si]
					si++
				}
			}
			continue
		}
		si := 0
		for yy := 0; yy < bh; yy++ {
			for xx := 0; xx < bw; xx++ {
				s := samples[si : si+spp]
				si += spp
				setSample(bx+xx, by+yy, s)
			}
		}
	}
	if inf.planar == 2 {
		for y := 0; y < h; y++ {
			for x := 0; x < w; x++ {
				setSample(x, y, planarBuf[y][x*spp:(x+1)*spp])
			}
		}
	}
	// Silence the unused-variable checks for block offsets that are
	// monotonically referenced only through inf.
	_ = sort.Ints
	return dst, nil
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func scaleSample(v uint32, bps int64) int {
	switch bps {
	case 1:
		if v == 0 {
			return 0
		}
		return 255
	case 2:
		return int(v) * 85
	case 4:
		return int(v) * 17
	case 8:
		return int(v)
	case 16:
		return int(v >> 8)
	default:
		return int(v)
	}
}

func readSamples(raw []byte, count, blockW, blockH int, inf *info, order binary.ByteOrder) ([]uint32, error) {
	bps := firstBPS(inf)
	out := make([]uint32, 0, count)
	switch bps {
	case 8:
		n := count
		if len(raw) < n {
			return out, invalid("not enough pixel data")
		}
		for _, b := range raw[:n] {
			out = append(out, uint32(b))
		}
	case 16:
		n := count * 2
		if len(raw) < n {
			return out, invalid("not enough pixel data")
		}
		for i := 0; i < count; i++ {
			out = append(out, uint32(order.Uint16(raw[i*2:])))
		}
	case 1, 2, 4:
		// Samples are packed; each row starts on a byte boundary.
		samplesPerRow := count / maxI(blockH, 1)
		br := &bitReader{data: raw, fillOrder: inf.fillOrder}
		for y := 0; y < blockH; y++ {
			for i := 0; i < samplesPerRow && len(out) < count; i++ {
				out = append(out, br.read(int(bps)))
			}
			br.align()
		}
		if len(out) < count {
			return out, invalid("not enough pixel data")
		}
	default:
		return nil, errColorModel
	}
	return out, nil
}

func maxI(a, b int) int {
	if a > b {
		return a
	}
	return b
}
