	data, err := io.ReadAll(r)
	if err != nil {
		return image.Config{}, err
	}
	chunks, err := parseRIFF(data)
	if err != nil {
		return image.Config{}, err
	}
	w, h, ok := libwebpGetInfo(data)
	if !ok {
		return image.Config{}, fmt.Errorf("webp: invalid image")
	}
	return image.Config{ColorModel: configModel(chunks), Width: w, Height: h}, nil
