func decodeLossless(data []byte, alphaUsed bool) (image.Image, error) {
	buf, w, h, ok := libwebpDecodeRGBA(data)
	if !ok {
		return nil, fmt.Errorf("webp: invalid image")
	}
	if alphaUsed {
		img := image.NewNRGBA(image.Rect(0, 0, w, h))
		for y := 0; y < h; y++ {
			for x := 0; x < w; x++ {
				i := (y*w + x) * 4
				img.Pix[i+0] = buf[i+0]
				img.Pix[i+1] = buf[i+1]
				img.Pix[i+2] = buf[i+2]
				img.Pix[i+3] = buf[i+3]
			}
		}
		return img, nil
	}
	img := image.NewRGBA(image.Rect(0, 0, w, h))
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			i := (y*w + x) * 4
			img.Pix[i+0] = buf[i+0]
			img.Pix[i+1] = buf[i+1]
			img.Pix[i+2] = buf[i+2]
			img.Pix[i+3] = 255
		}
	}
	return img, nil
