import "C"
import "unsafe"

func libwebpGetInfo(data []byte) (int, int, bool) {
	if len(data) == 0 {
		return 0, 0, false
	}
	var w, h C.int
	ok := C.get_info((*C.uint8_t)(unsafe.Pointer(&data[0])), C.size_t(len(data)), &w, &h)
	return int(w), int(h), ok != 0
}

func libwebpDecodeRGBA(data []byte) ([]byte, int, int, bool) {
	if len(data) == 0 {
		return nil, 0, 0, false
	}
	var w, h C.int
	p := C.decode_rgba((*C.uint8_t)(unsafe.Pointer(&data[0])), C.size_t(len(data)), &w, &h)
	if p == nil {
		return nil, 0, 0, false
	}
	defer C.free_mem(unsafe.Pointer(p))
	n := int(w) * int(h) * 4
	out := make([]byte, n)
	copy(out, unsafe.Slice((*byte)(unsafe.Pointer(p)), n))
	return out, int(w), int(h), true
}

func libwebpDecodeYUV(data []byte) (y, u, v []byte, w, h, ys, uvs int, ok bool) {
	if len(data) == 0 {
		return nil, nil, nil, 0, 0, 0, 0, false
	}
	var cw, ch, s, uv C.int
	var pu, pv *C.uint8_t
	p := C.decode_yuv((*C.uint8_t)(unsafe.Pointer(&data[0])), C.size_t(len(data)), &cw, &ch, &pu, &pv, &s, &uv)
	if p == nil {
		return nil, nil, nil, 0, 0, 0, 0, false
	}
	defer C.free_mem(unsafe.Pointer(p))
	w, h, ys, uvs = int(cw), int(ch), int(s), int(uv)
	y = append([]byte(nil), unsafe.Slice((*byte)(unsafe.Pointer(p)), ys*h)...)
	uvh := (h + 1) / 2
	u = append([]byte(nil), unsafe.Slice((*byte)(unsafe.Pointer(pu)), uvs*uvh)...)
	v = append([]byte(nil), unsafe.Slice((*byte)(unsafe.Pointer(pv)), uvs*uvh)...)
	return y, u, v, w, h, ys, uvs, true
}

func libwebpDecodeYUVA(data []byte) (y, u, v, a []byte, w, h, ys, uvs, as int, ok bool) {
	if len(data) == 0 {
		return nil, nil, nil, nil, 0, 0, 0, 0, 0, false
	}
	var cw, ch, s, uv, astride C.int
	var pu, pv, pa *C.uint8_t
	p := C.decode_yuva((*C.uint8_t)(unsafe.Pointer(&data[0])), C.size_t(len(data)), &cw, &ch, &pu, &pv, &pa, &s, &uv, &astride)
	if p == nil || pa == nil {
		if p != nil {
			C.free_mem(unsafe.Pointer(p))
		}
		return nil, nil, nil, nil, 0, 0, 0, 0, 0, false
	}
	defer C.free_mem(unsafe.Pointer(p))
	w, h, ys, uvs, as = int(cw), int(ch), int(s), int(uv), int(astride)
	y = append([]byte(nil), unsafe.Slice((*byte)(unsafe.Pointer(p)), ys*h)...)
	uvh := (h + 1) / 2
	u = append([]byte(nil), unsafe.Slice((*byte)(unsafe.Pointer(pu)), uvs*uvh)...)
	v = append([]byte(nil), unsafe.Slice((*byte)(unsafe.Pointer(pv)), uvs*uvh)...)
	a = append([]byte(nil), unsafe.Slice((*byte)(unsafe.Pointer(pa)), as*h)...)
	return y, u, v, a, w, h, ys, uvs, as, true
}
