// Package webp registers a WebP decoder. Decoding is delegated to the
// system libwebp (loaded dynamically) and the results are returned in the
// same image representations used by common Go WebP decoders: YCbCr for
// lossy VP8, NYCbCrA for lossy VP8 with alpha, and RGBA/NRGBA for VP8L.
package webp

import (
	"encoding/binary"
	"errors"
	"fmt"
	"image"
	"image/color"
	"io"
)

func init() {
	image.RegisterFormat("webp", "RIFF????WEBPVP8", Decode, DecodeConfig)
}

type chunk struct {
	fourCC string
	data   []byte
}

func parseRIFF(data []byte) ([]chunk, error) {
	if len(data) < 12 {
		return nil, errors.New("riff: short chunk header")
	}
	if string(data[0:4]) != "RIFF" || string(data[8:12]) != "WEBP" {
		return nil, image.ErrFormat
	}
	var chunks []chunk
	for off := 12; off < len(data); {
		if len(data)-off < 8 {
			return nil, errors.New("riff: short chunk header")
		}
		four := string(data[off : off+4])
		size := int64(binary.LittleEndian.Uint32(data[off+4 : off+8]))
		off += 8
		if size < 0 || int64(len(data)-off) < size {
			return nil, errors.New("riff: short chunk data")
		}
		chunks = append(chunks, chunk{fourCC: four, data: data[off : off+int(size)]})
		off += int(size)
		if size%2 == 1 {
			off++ // RIFF chunks are padded to even sizes
		}
	}
	return chunks, nil
}

func findChunk(chunks []chunk, four string) *chunk {
	for i := range chunks {
		if chunks[i].fourCC == four {
			return &chunks[i]
		}
	}
	return nil
}

func vp8lAlphaUsed(c *chunk) bool {
	if c == nil || len(c.data) < 5 {
		return false
	}
	v := binary.LittleEndian.Uint32(c.data[1:5])
	return (v>>28)&1 == 1
}

func configModel(chunks []chunk) color.Model {
	if findChunk(chunks, "VP8L") != nil {
		if vp8lAlphaUsed(findChunk(chunks, "VP8L")) {
			return color.NRGBAModel
		}
		return color.RGBAModel
	}
	if findChunk(chunks, "VP8X") != nil {
		// VP8X feature flags byte is the first payload byte; alpha is bit 4.
		if c := findChunk(chunks, "VP8X"); len(c.data) > 0 && c.data[0]&0x10 != 0 {
			return color.NRGBAModel
		}
		if findChunk(chunks, "VP8 ") != nil {
			return color.YCbCrModel
		}
		return color.RGBAModel
	}
	if findChunk(chunks, "VP8 ") != nil {
		return color.YCbCrModel
	}
	return color.RGBAModel
}

func DecodeConfig(r io.Reader) (image.Config, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return image.Config{}, err
	}
	chunks, err := parseRIFF(data)
	if err != nil {
		return image.Config{}, err
	}
	w, h, ok := libwebpGetInfo(data)
	if !ok {
		return image.Config{}, fmt.Errorf("webp: invalid image")
	}
	return image.Config{ColorModel: configModel(chunks), Width: w, Height: h}, nil
}

func Decode(r io.Reader) (image.Image, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}
	chunks, err := parseRIFF(data)
	if err != nil {
		return nil, err
	}
	hasL := findChunk(chunks, "VP8L") != nil
	hasX := findChunk(chunks, "VP8X") != nil
	hasLossy := findChunk(chunks, "VP8 ") != nil

	if hasL && !hasX {
		return decodeLossless(data, vp8lAlphaUsed(findChunk(chunks, "VP8L")))
	}
	if hasLossy && !hasX {
		return decodeLossy(data, false)
	}
	if hasX {
		x := findChunk(chunks, "VP8X")
		alpha := len(x.data) > 0 && x.data[0]&0x10 != 0
		if hasLossy {
			return decodeLossy(data, alpha)
		}
		// Extended lossless (or animated) content: ask libwebp for RGBA.
		return decodeLossless(data, alpha)
	}
	return nil, fmt.Errorf("webp: no VP8 chunk")
}

func decodeLossless(data []byte, alphaUsed bool) (image.Image, error) {
	buf, w, h, ok := libwebpDecodeRGBA(data)
	if !ok {
		return nil, fmt.Errorf("webp: invalid image")
	}
	if alphaUsed {
		img := image.NewNRGBA(image.Rect(0, 0, w, h))
		for y := 0; y < h; y++ {
			for x := 0; x < w; x++ {
				i := (y*w + x) * 4
				img.Pix[i+0] = buf[i+0]
				img.Pix[i+1] = buf[i+1]
				img.Pix[i+2] = buf[i+2]
				img.Pix[i+3] = buf[i+3]
			}
		}
		return img, nil
	}
	img := image.NewRGBA(image.Rect(0, 0, w, h))
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			i := (y*w + x) * 4
			img.Pix[i+0] = buf[i+0]
			img.Pix[i+1] = buf[i+1]
			img.Pix[i+2] = buf[i+2]
			img.Pix[i+3] = 255
		}
	}
	return img, nil
}

func copyPlane(plane []byte, w, h, stride int) []byte {
	out := make([]byte, w*h)
	for y := 0; y < h; y++ {
		copy(out[y*w:(y+1)*w], plane[y*stride:y*stride+w])
	}
	return out
}

func decodeLossy(data []byte, alpha bool) (image.Image, error) {
	if alpha {
		y, u, v, a, w, h, ys, uvs, as, ok := libwebpDecodeYUVA(data)
		if ok {
			cw, ch := (w+1)/2, (h+1)/2
			// image.NYCbCrA shares layout with YCbCr plus an alpha plane.
			img := &image.NYCbCrA{
				YCbCr: image.YCbCr{
					Y:              copyPlane(y, w, h, ys),
					Cb:             copyPlane(u, cw, ch, uvs),
					Cr:             copyPlane(v, cw, ch, uvs),
					YStride:        w,
					CStride:        cw,
					SubsampleRatio: image.YCbCrSubsampleRatio420,
					Rect:           image.Rect(0, 0, w, h),
				},
				A:       copyPlane(a, w, h, as),
				AStride: w,
			}
			return img, nil
		}
		// Fall through to RGBA decoding if YUVA is unavailable.
		return decodeLossless(data, true)
	}
	y, u, v, w, h, ys, uvs, ok := libwebpDecodeYUV(data)
	if !ok {
		return nil, fmt.Errorf("webp: invalid image")
	}
	cw, ch := (w+1)/2, (h+1)/2
	return &image.YCbCr{
		Y:              copyPlane(y, w, h, ys),
		Cb:             copyPlane(u, cw, ch, uvs),
		Cr:             copyPlane(v, cw, ch, uvs),
		YStride:        w,
		CStride:        cw,
		SubsampleRatio: image.YCbCrSubsampleRatio420,
		Rect:           image.Rect(0, 0, w, h),
	}, nil
}
