    for f in glob.glob('/tmp/glyph_probe/*'):os.remove(f)
    if braille_bits is None:
        # map with char repeated; if ch is '-' use --map= to avoid flag weirdness? Args list with -m value '--' works pflag.
        m=ch*2
        args=['/tmp/ref_executable','/tmp/white4.png','-d','1,1','-m',m,'-s','/tmp/glyph_probe','--only-save']
    else:
        # create 2x4 image for desired bits via png generator used earlier: direct make
        import struct,zlib
        pix=[]
        bitsmap={(0,0):1,(1,0):8,(0,1):2,(1,1):16,(0,2):4,(1,2):32,(0,3):64,(1,3):128}
        for y in range(4):
            row=[]
            for x in range(2):row.append((255,255,255) if braille_bits&bitsmap[(x,y)] else (0,0,0))
            pix.append(row)
        def write(path,w,h,pix):
            def chunk(t,d): return struct.pack('>I',len(d))+t+d+struct.pack('>I',zlib.crc32(t+d)&0xffffffff)
            raw=b''
            for yy in range(h):
                raw+=b'\x00'
                for xx in range(w):raw+=bytes(pix[yy][xx])
            ihdr=struct.pack('>IIBBBBB',w,h,8,2,0,0,0);open(path,'wb').write(b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',ihdr)+chunk(b'IDAT',zlib.compress(raw))+chunk(b'IEND',b''))
