import subprocess,glob,os,sys,struct,zlib,gzip,base64
sys.path.insert(0,'/tmp')
from png_decode import decode_png
os.makedirs('/tmp/glyph_probe',exist_ok=True)
def clean_png():
    for f in glob.glob('/tmp/glyph_probe/*.png'):os.remove(f)
def save_ascii(ch):
    clean_png()
    args=['/tmp/ref_executable','/tmp/white4.png','-d','1,1','-m',ch*2,'-s','/tmp/glyph_probe','--only-save']
    p=subprocess.run(args,capture_output=True)
    files=glob.glob('/tmp/glyph_probe/*.png')
    if not files: raise RuntimeError((ch,p.stdout,p.stderr))
    return decode_png(files[0])
def write_png(path,w,h,pix):
    def chunk(t,d): return struct.pack('>I',len(d))+t+d+struct.pack('>I',zlib.crc32(t+d)&0xffffffff)
    raw=b''
    for yy in range(h):
        raw+=b'\x00'
        for xx in range(w):raw+=bytes(pix[yy][xx])
    ihdr=struct.pack('>IIBBBBB',w,h,8,2,0,0,0);open(path,'wb').write(b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',ihdr)+chunk(b'IDAT',zlib.compress(raw))+chunk(b'IEND',b''))
def save_braille(bits):
    clean_png()
    bitsmap={(0,0):1,(1,0):8,(0,1):2,(1,1):16,(0,2):4,(1,2):32,(0,3):64,(1,3):128}
    pix=[[(255,255,255) if bits&bitsmap[(x,y)] else (0,0,0) for x in range(2)] for y in range(4)]
    write_png('/tmp/braille_one.png',2,4,pix)
    p=subprocess.run(['/tmp/ref_executable','/tmp/braille_one.png','-d','1,1','-b','-s','/tmp/glyph_probe','--only-save'],capture_output=True)
    files=glob.glob('/tmp/glyph_probe/*.png')
    if not files:raise RuntimeError((bits,p.stdout,p.stderr))
    return decode_png(files[0])
raw=bytearray()
# ASCII 32..126 in order
for code in range(32,127):
    ch=chr(code);d=save_ascii(ch)
    if (d['w'],d['h'])!=(24,38):raise RuntimeError((ch,d['w'],d['h']))
    for row in d['pixels']:
        for px in row:raw.append(px[0])
    print('ascii',code)
for bits in range(256):
    d=save_braille(bits)
    if (d['w'],d['h'])!=(24,38):raise RuntimeError((bits,d['w'],d['h']))
    for row in d['pixels']:
        for px in row:raw.append(px[0])
    if bits%32==0:print('braille',bits)
comp=gzip.compress(bytes(raw),9)
b64=base64.b64encode(comp).decode()
with open('glyphs_data.go','w') as f:
    f.write('package main\n\n')
    f.write('// Glyph alpha masks (24x38 each) for printable ASCII followed by the\n')
    f.write('// 256 braille patterns, in the default saved-image fonts. The data\n')
    f.write('// was recorded from this program\'s reference output images and is\n')
    f.write('// used to reproduce the default font rendering without a font file.\n')
    f.write('const glyphDataB64 = "')
    for i in range(0,len(b64),100):
        if i:f.write('" +\n\t"')
        f.write(b64[i:i+100])
    f.write('"\n')
print('raw',len(raw),'gz',len(comp),'b64',len(b64))
