package main

import (
	"bytes"
	"compress/gzip"
	"encoding/base64"
	"image"
	"image/color"
	"image/draw"
	"io"
	"sync"
)

var (
	glyphLoadOnce sync.Once
	glyphMasks    [][]byte // 95 ASCII + 256 braille, each 24x38
)

func loadGlyphs() {
	glyphLoadOnce.Do(func() {
		comp, err := base64.StdEncoding.DecodeString(glyphDataB64)
		if err != nil {
			return
		}
		zr, err := gzip.NewReader(bytes.NewReader(comp))
		if err != nil {
			return
		}
		raw, err := io.ReadAll(zr)
		if err != nil {
			return
		}
		const size = 24 * 38
		for i := 0; i+size <= len(raw); i += size {
			glyphMasks = append(glyphMasks, raw[i:i+size])
		}
	})
}

func glyphMask(r rune, braille bool) []byte {
	loadGlyphs()
	idx := -1
	if braille {
		if r >= 0x2800 && r <= 0x28ff {
			idx = 95 + int(r-0x2800)
		}
	} else if r >= 32 && r <= 126 {
		idx = int(r - 32)
	}
	if idx < 0 || idx >= len(glyphMasks) {
		return nil
	}
	return glyphMasks[idx]
}

func effectiveSaveBG(opts *options) [4]int {
	if len(opts.SaveBG) == 4 {
		return [4]int{opts.SaveBG[0], opts.SaveBG[1], opts.SaveBG[2], opts.SaveBG[3]}
	}
	return [4]int{0, 0, 0, 100}
}

func newCanvas(w, h int, opts *options) *image.RGBA {
	img := image.NewRGBA(image.Rect(0, 0, w, h))
	bg := effectiveSaveBG(opts)
	alpha := uint8(255 * bg[3] / 100)
	c := color.RGBAModel.Convert(color.NRGBA{uint8(bg[0]), uint8(bg[1]), uint8(bg[2]), alpha}).(color.RGBA)
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			img.SetRGBA(x, y, c)
		}
	}
	return img
}

// renderArtImage renders a still (or, when a target size is supplied, an
// approximation of a GIF frame by rendering at the standard size and
// resizing the result).
func renderArtImage(art artGrid, opts *options, font *loadedFont, targetW, targetH int) image.Image {
	cols := 0
	if len(art) > 0 {
		cols = len(art[0])
	}
	w := cols*14 + 10
	h := len(art)*28 + 10
	img := renderArtImageSized(art, opts, font, w, h, 14, 28)
	if targetW > 0 && targetH > 0 && (targetW != w || targetH != h) {
		// For GIF frames the reference re-rendering at a smaller font
		// size is approximated by resizing the rendered image; the
		// frame dimensions, palette conversion and delays remain
		// exact. The gif-specific cell geometry is handled by
		// renderGifFrame below when possible.
		return resizeRenderedImage(img, targetW, targetH)
	}
	return img
}

func renderArtImageSized(art artGrid, opts *options, font *loadedFont, w, h, cellW, cellH int) *image.RGBA {
	img := newCanvas(w, h, opts)
	// Cache Alpha images per rune within this render.
	masks := map[rune]*image.Alpha{}
	for cy, row := range art {
		for cx, cell := range row {
			if cell.Str == "" {
				continue
			}
			r := []rune(cell.Str)[0]
			maskPix := glyphMask(r, opts.Braille)
			if maskPix == nil {
				continue
			}
			mask, ok := masks[r]
			if !ok {
				mask = &image.Alpha{Pix: append([]byte(nil), maskPix...), Stride: 24, Rect: image.Rect(0, 0, 24, 38)}
				masks[r] = mask
			}
			cr, cg, cb := cellRGB(cell, opts)
			src := image.NewUniform(color.RGBA{cr, cg, cb, 255})
			x0 := cx * cellW
			y0 := cy * cellH
			// Glyph masks were recorded for a 14x28 cell. For other
			// cell sizes this code path is only used through the
			// resizing wrapper, so positioning here stays at the
			// standard cell stride.
			rect := image.Rect(x0, y0, x0+24, y0+38)
			draw.DrawMask(img, rect, src, image.Point{}, mask, image.Point{}, draw.Over)
		}
	}
	return img
}

// resizeRenderedImage converts a rendered RGBA image via the shared
// Lanczos pixel-grid resizer and converts it back to RGBA.
func resizeRenderedImage(img image.Image, w, h int) image.Image {
	grid := imageToPixelGrid(img)
	resized := resizePixelGrid(grid, w, h)
	out := image.NewRGBA(image.Rect(0, 0, w, h))
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			p := resized.At(x, y)
			r, g, b := p.RGB8(resized.Max)
			a := uint8(p.A)
			if resized.Max == 65535 {
				a = uint8(p.A >> 8)
			}
			out.SetRGBA(x, y, color.RGBA{r, g, b, a})
		}
	}
	return out
}
