func renderArtImageSized(art artGrid, opts *options, font *loadedFont, w, h, cellW, cellH int) *image.RGBA {
	img := newCanvas(w, h, opts)
	// Cache Alpha images per rune within this render.
	masks := map[rune]*image.Alpha{}
	for cy, row := range art {
		for cx, cell := range row {
			if cell.Str == "" {
				continue
			}
			r := []rune(cell.Str)[0]
			maskPix := glyphMask(r, opts.Braille)
			if maskPix == nil {
				continue
			}
			mask, ok := masks[r]
			if !ok {
				mask = &image.Alpha{Pix: append([]byte(nil), maskPix...), Stride: 24, Rect: image.Rect(0, 0, 24, 38)}
				masks[r] = mask
			}
			cr, cg, cb := cellRGB(cell, opts)
			src := image.NewUniform(color.RGBA{cr, cg, cb, 255})
			x0 := cx * cellW
			y0 := cy * cellH
			// Glyph masks were recorded for a 14x28 cell. For other
			// cell sizes this code path is only used through the
			// resizing wrapper, so positioning here stays at the
			// standard cell stride.
			rect := image.Rect(x0, y0, x0+24, y0+38)
			draw.DrawMask(img, rect, src, image.Point{}, mask, image.Point{}, draw.Over)
		}
	}
	return img
}

// resizeRenderedImage converts a rendered RGBA image via the shared
// Lanczos pixel-grid resizer and converts it back to RGBA.
func resizeRenderedImage(img image.Image, w, h int) image.Image {
	grid := imageToPixelGrid(img)
	resized := resizePixelGrid(grid, w, h)
	out := image.NewRGBA(image.Rect(0, 0, w, h))
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			p := resized.At(x, y)
			r, g, b := p.RGB8(resized.Max)
			a := uint8(p.A)
			if resized.Max == 65535 {
				a = uint8(p.A >> 8)
			}
			out.SetRGBA(x, y, color.RGBA{r, g, b, a})
		}
	}
	return out
}
