func sinc(x float64)float64{if x==0{return 1};return math.Sin(math.Pi*x)/(math.Pi*x)}
func lancA(x float64)float64{if x==0{return 1}; if math.Abs(x)>=3{return 0}; return (math.Sin(math.Pi*x)/(math.Pi*x))*(math.Sin(math.Pi*x/3)/(math.Pi*x/3))}
