}

func resizeCoeffs(inN, outN int) [][]coeff {
	scale32 := float32(inN) / float32(outN)
	filterScale32 := scale32
	if filterScale32 < 1 {
		filterScale32 = 1
	}
	support := float64(3 * filterScale32)
	all := make([][]coeff, outN)
	for j := 0; j < outN; j++ {
		center32 := (float32(j)+0.5)*scale32 - 0.5
		center := float64(center32)
		start := int(math.Ceil(center - support))
		if start < 0 {
			start = 0
		}
		end := int(math.Floor(center + support))
		if end >= inN {
			end = inN - 1
		}
		var list []coeff
		for i := start; i <= end; i++ {
			w := lanczos3(float64((float32(i) - center32) / filterScale32))
			if w == 0 {
				continue
			}
			list = append(list, coeff{idx: i, w: w})
		}
		all[j] = list
	}
	return all
}

