package main

import (
	"encoding/binary"
	"errors"
	"fmt"
	"os"
)

type loadedFont struct {
	path string
	data []byte
	ttf  *ttfFont
}

func loadFontIfRequested(opts *options) (*loadedFont, error) {
	if opts.Font == "" {
		return nil, nil
	}
	data, err := os.ReadFile(opts.Font)
	if err != nil {
		return nil, fmt.Errorf("unable to open font file: %v", err)
	}
	parsed, err := parseTTF(data)
	if err != nil {
		return nil, fmt.Errorf("unable to parse font file: %v", err)
	}
	return &loadedFont{path: opts.Font, data: data, ttf: parsed}, nil
}

var errTTFTooShort = errors.New("freetype: invalid TrueType format: TTF data is too short")

type ttfFont struct {
	data             []byte
	tables           map[string][]byte
	unitsPerEm       int
	indexToLocFormat int16
	numGlyphs        int
	numHMetrics      int
	ascent           int16
	descent          int16
	lineGap          int16
	advances         []uint16
	lsbs             []int16
	cmapFormat       int
	cmap             []byte
	kern             map[[2]uint16]int16
	bounds           [4]int16 // xMin,yMin,xMax,yMax from head
}

func u16(b []byte, off int) uint16 { return binary.BigEndian.Uint16(b[off:]) }
func i16(b []byte, off int) int16  { return int16(u16(b, off)) }
func u32(b []byte, off int) uint32 { return binary.BigEndian.Uint32(b[off:]) }

func parseTTF(data []byte) (*ttfFont, error) {
	if len(data) >= 4 && string(data[:4]) == "ttcf" {
		if len(data) < 12 {
			return nil, errTTFTooShort
		}
		version := u32(data, 4)
		if version != 0x00010000 && version != 0x00020000 {
			return nil, errors.New("freetype: invalid TrueType format: bad TTC version")
		}
		numFonts := u32(data, 8)
		if numFonts == 0 || 12+4*int64(numFonts) > int64(len(data)) {
			return nil, errTTFTooShort
		}
		off := u32(data, 12)
		if int64(off) >= int64(len(data)) {
			return nil, errTTFTooShort
		}
		return parseSFNT(data, int(off))
	}
	return parseSFNT(data, 0)
}

func parseSFNT(data []byte, base int) (*ttfFont, error) {
	if len(data)-base < 12 {
		return nil, errTTFTooShort
	}
	if u32(data, base) != 0x00010000 {
		return nil, errors.New("freetype: invalid TrueType format: bad TTF version")
	}
	numTables := int(u16(data, base+4))
	if base+12+16*numTables > len(data) {
		return nil, errTTFTooShort
	}
	f := &ttfFont{data: data, tables: map[string][]byte{}, kern: map[[2]uint16]int16{}}
	for i := 0; i < numTables; i++ {
		e := base + 12 + 16*i
		tag := string(data[e : e+4])
		off := u32(data, e+8)
		length := u32(data, e+12)
		if uint64(off)+uint64(length) > uint64(len(data)) {
			// The reference parser's message reports the (possibly
			// wrapping) 32-bit sum.
			return nil, fmt.Errorf("freetype: invalid TrueType format: offset + length too large: %d", off+length)
		}
		f.tables[tag] = data[int(off):int(off+length)]
	}

	// kern is examined by the reference parser before some other tables;
	// a present-but-short kern table is an error.
	if kern, ok := f.tables["kern"]; ok && len(kern) > 0 {
		if err := f.parseKern(kern); err != nil {
			return nil, err
		}
	}

	head := f.tables["head"]
	if len(head) != 54 {
		return nil, fmt.Errorf("freetype: invalid TrueType format: bad head length: %d", len(head))
	}
	f.unitsPerEm = int(u16(head, 18))
	f.bounds = [4]int16{i16(head, 36), i16(head, 38), i16(head, 40), i16(head, 42)}
	f.indexToLocFormat = i16(head, 50)

	maxp := f.tables["maxp"]
	if len(maxp) != 32 {
		return nil, fmt.Errorf("freetype: invalid TrueType format: bad maxp length: %d", len(maxp))
	}
	f.numGlyphs = int(u16(maxp, 4))

	if err := f.parseCmap(f.tables["cmap"]); err != nil {
		return nil, err
	}

	hhea := f.tables["hhea"]
	if len(hhea) != 36 {
		return nil, fmt.Errorf("freetype: invalid TrueType format: bad hhea length: %d", len(hhea))
	}
	f.ascent = i16(hhea, 4)
	f.descent = i16(hhea, 6)
	f.lineGap = i16(hhea, 8)
	f.numHMetrics = int(u16(hhea, 34))

	hmtx := f.tables["hmtx"]
	expectedHmtx := 2*f.numGlyphs + 2*f.numHMetrics
	if len(hmtx) != expectedHmtx {
		return nil, fmt.Errorf("freetype: invalid TrueType format: bad hmtx length: %d", len(hmtx))
	}
	f.advances = make([]uint16, f.numGlyphs)
	f.lsbs = make([]int16, f.numGlyphs)
	for i := 0; i < f.numGlyphs; i++ {
		if i < f.numHMetrics {
			f.advances[i] = u16(hmtx, 4*i)
			f.lsbs[i] = i16(hmtx, 4*i+2)
		} else {
			if f.numHMetrics > 0 {
				f.advances[i] = f.advances[f.numHMetrics-1]
			}
			off := 4*f.numHMetrics + 2*(i-f.numHMetrics)
			f.lsbs[i] = i16(hmtx, off)
		}
	}
	return f, nil
}

func (f *ttfFont) parseKern(kern []byte) error {
	if len(kern) < 4 {
		return errors.New("freetype: invalid TrueType format: kern data too short")
	}
	nTables := int(u16(kern, 2))
	off := 4
	for i := 0; i < nTables; i++ {
		if off+6 > len(kern) {
			return errors.New("freetype: invalid TrueType format: kern data too short")
		}
		length := int(u16(kern, off))
		coverage := u16(kern, off+2)
		if length < 6 || off+length > len(kern) {
			return errors.New("freetype: invalid TrueType format: kern data too short")
		}
		format := coverage >> 8
		if format == 0 {
			if length < 14 {
				return errors.New("freetype: invalid TrueType format: kern data too short")
			}
			nPairs := int(u16(kern, off+6))
			if 14+6*nPairs > length {
				return errors.New("freetype: invalid TrueType format: kern data too short")
			}
			for p := 0; p < nPairs; p++ {
				po := off + 14 + 6*p
				f.kern[[2]uint16{u16(kern, po), u16(kern, po+2)}] = i16(kern, po+4)
			}
		}
		off += length
	}
	return nil
}

var supportedCmapEncodings = [][2]uint16{{0, 3}, {0, 4}, {3, 0}, {3, 1}, {3, 10}}

func (f *ttfFont) parseCmap(cmap []byte) error {
	if len(cmap) < 4 {
		return errors.New("freetype: invalid TrueType format: cmap too short")
	}
	num := int(u16(cmap, 2))
	if len(cmap) < 4+8*num {
		return errors.New("freetype: invalid TrueType format: cmap too short")
	}
	for i := 0; i < num; i++ {
		off := 4 + 8*i
		plat, enc := u16(cmap, off), u16(cmap, off+2)
		supported := false
		for _, s := range supportedCmapEncodings {
			if plat == s[0] && enc == s[1] {
				supported = true
				break
			}
		}
		if !supported {
			continue
		}
		subOff := int(u32(cmap, off+4))
		if subOff < 0 || subOff+2 > len(cmap) {
			return errors.New("freetype: invalid TrueType format: cmap too short")
		}
		sub := cmap[subOff:]
		format := u16(sub, 0)
		switch format {
		case 4:
			f.cmapFormat = 4
			f.cmap = sub
			return nil
		case 12:
			if len(sub) < 4 || u16(sub, 2) != 0 {
				if len(sub) >= 4 {
					return fmt.Errorf("freetype: invalid TrueType format: cmap format: % x", sub[:4])
				}
				return errors.New("freetype: invalid TrueType format: cmap too short")
			}
			if len(sub) < 16 {
				return errors.New("freetype: invalid TrueType format: cmap too short")
			}
			f.cmapFormat = 12
			f.cmap = sub
			return nil
		default:
			return fmt.Errorf("freetype: unsupported TrueType feature: cmap format: %d", format)
		}
	}
	return errors.New("freetype: unsupported TrueType feature: cmap encoding")
}

// glyphIndex maps a rune to a glyph index using cmap format 4 or 12.
func (f *ttfFont) glyphIndex(r rune) int {
	if r < 0 {
		return 0
	}
	switch f.cmapFormat {
	case 4:
		if r > 0xffff || len(f.cmap) < 14 {
			return 0
		}
		segCount := int(u16(f.cmap, 6) / 2)
		// Layout: header(14), endCode[seg], reserved(2), startCode[seg],
		// idDelta[seg], idRangeOffset[seg], glyphIdArray.
		endOff := 14
		startOff := endOff + 2*segCount + 2
		deltaOff := startOff + 2*segCount
		rangeOff := deltaOff + 2*segCount
		if rangeOff+2*segCount > len(f.cmap) {
			return 0
		}
		for s := 0; s < segCount; s++ {
			end := uint32(u16(f.cmap, endOff+2*s))
			if uint32(r) > end {
				continue
			}
			start := uint32(u16(f.cmap, startOff+2*s))
			if uint32(r) < start {
				return 0
			}
			delta := int32(i16(f.cmap, deltaOff+2*s))
			ro := int(u16(f.cmap, rangeOff+2*s))
			if ro == 0 {
				return int((int32(r) + delta) & 0xffff)
			}
			idxPos := rangeOff + 2*s + ro + 2*int(uint32(r)-start)
			if idxPos+1 >= len(f.cmap) {
				return 0
			}
			gid := int(u16(f.cmap, idxPos))
			if gid != 0 {
				gid = (gid + int(delta)) & 0xffff
			}
			return gid
		}
		return 0
	case 12:
		if len(f.cmap) < 16 {
			return 0
		}
		n := int(u32(f.cmap, 12))
		for i := 0; i < n; i++ {
			off := 16 + 12*i
			if off+12 > len(f.cmap) {
				return 0
			}
			start := u32(f.cmap, off)
			end := u32(f.cmap, off+4)
			base := u32(f.cmap, off+8)
			if uint32(r) >= start && uint32(r) <= end {
				return int(base + uint32(r) - start)
			}
			if uint32(r) < start {
				return 0
			}
		}
	}
	return 0
}
