			if plat == s[0] && enc == s[1] {
				supported = true
				break
			}
		}
		if !supported {
			continue
		}
		subOff := int(u32(cmap, off+4))
		if subOff < 0 || subOff+2 > len(cmap) {
			return errors.New("freetype: invalid TrueType format: cmap too short")
		}
		sub := cmap[subOff:]
		format := u16(sub, 0)
		switch format {
		case 4:
			f.cmapFormat = 4
			f.cmap = sub
			return nil
		case 12:
			if len(sub) < 4 || u16(sub, 2) != 0 {
				if len(sub) >= 4 {
					return fmt.Errorf("freetype: invalid TrueType format: cmap format: % x", sub[:4])
				}
				return errors.New("freetype: invalid TrueType format: cmap too short")
			}
			if len(sub) < 16 {
				return errors.New("freetype: invalid TrueType format: cmap too short")
			}
			f.cmapFormat = 12
			f.cmap = sub
			return nil
		default:
			return fmt.Errorf("freetype: unsupported TrueType feature: cmap format: %d", format)
		}
	}
	return errors.New("freetype: unsupported TrueType feature: cmap encoding")
}

// glyphIndex maps a rune to a glyph index using cmap format 4 or 12.
func (f *ttfFont) glyphIndex(r rune) int {
	if r < 0 {
		return 0
	}
	switch f.cmapFormat {
	case 4:
		if r > 0xffff || len(f.cmap) < 14 {
			return 0
		}
		segCount := int(u16(f.cmap, 6) / 2)
		// Layout: header(14), endCode[seg], reserved(2), startCode[seg],
		// idDelta[seg], idRangeOffset[seg], glyphIdArray.
		endOff := 14
		startOff := endOff + 2*segCount + 2
		deltaOff := startOff + 2*segCount
		rangeOff := deltaOff + 2*segCount
		if rangeOff+2*segCount > len(f.cmap) {
			return 0
		}
		for s := 0; s < segCount; s++ {
			end := uint32(u16(f.cmap, endOff+2*s))
			if uint32(r) > end {
				continue
			}
			start := uint32(u16(f.cmap, startOff+2*s))
			if uint32(r) < start {
				return 0
			}
			delta := int32(i16(f.cmap, deltaOff+2*s))
			ro := int(u16(f.cmap, rangeOff+2*s))
			if ro == 0 {
				return int((int32(r) + delta) & 0xffff)
			}
			idxPos := rangeOff + 2*s + ro + 2*int(uint32(r)-start)
			if idxPos+1 >= len(f.cmap) {
				return 0
			}
			gid := int(u16(f.cmap, idxPos))
			if gid != 0 {
				gid = (gid + int(delta)) & 0xffff
			}
			return gid
		}
		return 0
	case 12:
		if len(f.cmap) < 16 {
			return 0
		}
		n := int(u32(f.cmap, 12))
		for i := 0; i < n; i++ {
			off := 16 + 12*i
			if off+12 > len(f.cmap) {
				return 0
			}
			start := u32(f.cmap, off)
			end := u32(f.cmap, off+4)
			base := u32(f.cmap, off+8)
			if uint32(r) >= start && uint32(r) <= end {
				return int(base + uint32(r) - start)
			}
			if uint32(r) < start {
				return 0
			}
		}
	}
	return 0
}
