func loadFontIfRequested(opts *options) (*loadedFont, error) {
	if opts.Font == "" {
		return nil, nil
	}
	data, err := os.ReadFile(opts.Font)
	if err != nil {
		return nil, fmt.Errorf("unable to open font file: %v", err)
	}
	parsed, err := parseTTF(data)
	if err != nil {
		return nil, fmt.Errorf("unable to parse font file: %v", err)
	}
	return &loadedFont{path: opts.Font, data: data, ttf: parsed}, nil
}

var errTTFTooShort = errors.New("freetype: invalid TrueType format: TTF data is too short")

type ttfFont struct {
	data             []byte
	tables           map[string][]byte
	unitsPerEm       int
	indexToLocFormat int16
	numGlyphs        int
	numHMetrics      int
	ascent           int16
	descent          int16
	lineGap          int16
	advances         []uint16
	lsbs             []int16
	cmapFormat       int
	cmap             []byte
	kern             map[[2]uint16]int16
	bounds           [4]int16 // xMin,yMin,xMax,yMax from head
}

func u16(b []byte, off int) uint16 { return binary.BigEndian.Uint16(b[off:]) }
func i16(b []byte, off int) int16  { return int16(u16(b, off)) }
func u32(b []byte, off int) uint32 { return binary.BigEndian.Uint32(b[off:]) }

func parseTTF(data []byte) (*ttfFont, error) {
	if len(data) >= 4 && string(data[:4]) == "ttcf" {
		if len(data) < 12 {
			return nil, errTTFTooShort
		}
		version := u32(data, 4)
		if version != 0x00010000 && version != 0x00020000 {
			return nil, errors.New("freetype: invalid TrueType format: bad TTC version")
		}
		numFonts := u32(data, 8)
		if numFonts == 0 || 12+4*int64(numFonts) > int64(len(data)) {
			return nil, errTTFTooShort
		}
		off := u32(data, 12)
		if int64(off) >= int64(len(data)) {
			return nil, errTTFTooShort
		}
		return parseSFNT(data, int(off))
	}
	return parseSFNT(data, 0)
}

func parseSFNT(data []byte, base int) (*ttfFont, error) {
	if len(data)-base < 12 {
		return nil, errTTFTooShort
	}
	if u32(data, base) != 0x00010000 {
		return nil, errors.New("freetype: invalid TrueType format: bad TTF version")
	}
	numTables := int(u16(data, base+4))
	if base+12+16*numTables > len(data) {
		return nil, errTTFTooShort
