	f := &ttfFont{data: data, tables: map[string][]byte{}, kern: map[[2]uint16]int16{}}
	for i := 0; i < numTables; i++ {
		e := base + 12 + 16*i
		tag := string(data[e : e+4])
		off := u32(data, e+8)
		length := u32(data, e+12)
		if uint64(off)+uint64(length) > uint64(len(data)) {
			// The reference parser's message reports the (possibly
			// wrapping) 32-bit sum.
			return nil, fmt.Errorf("freetype: invalid TrueType format: offset + length too large: %d", off+length)
		}
		f.tables[tag] = data[int(off):int(off+length)]
	}

	// kern is examined by the reference parser before some other tables;
	// a present-but-short kern table is an error.
	if kern, ok := f.tables["kern"]; ok && len(kern) > 0 {
		if err := f.parseKern(kern); err != nil {
			return nil, err
		}
	}

	head := f.tables["head"]
	if len(head) != 54 {
		return nil, fmt.Errorf("freetype: invalid TrueType format: bad head length: %d", len(head))
	}
	f.unitsPerEm = int(u16(head, 18))
	f.bounds = [4]int16{i16(head, 36), i16(head, 38), i16(head, 40), i16(head, 42)}
	f.indexToLocFormat = i16(head, 50)

	maxp := f.tables["maxp"]
	if len(maxp) != 32 {
		return nil, fmt.Errorf("freetype: invalid TrueType format: bad maxp length: %d", len(maxp))
	}
	f.numGlyphs = int(u16(maxp, 4))

	if err := f.parseCmap(f.tables["cmap"]); err != nil {
		return nil, err
	}

	hhea := f.tables["hhea"]
	if len(hhea) != 36 {
		return nil, fmt.Errorf("freetype: invalid TrueType format: bad hhea length: %d", len(hhea))
	}
	f.ascent = i16(hhea, 4)
	f.descent = i16(hhea, 6)
	f.lineGap = i16(hhea, 8)
	f.numHMetrics = int(u16(hhea, 34))

	hmtx := f.tables["hmtx"]
	expectedHmtx := 2*f.numGlyphs + 2*f.numHMetrics
	if len(hmtx) != expectedHmtx {
		return nil, fmt.Errorf("freetype: invalid TrueType format: bad hmtx length: %d", len(hmtx))
	}
	f.advances = make([]uint16, f.numGlyphs)
	f.lsbs = make([]int16, f.numGlyphs)
	for i := 0; i < f.numGlyphs; i++ {
		if i < f.numHMetrics {
			f.advances[i] = u16(hmtx, 4*i)
			f.lsbs[i] = i16(hmtx, 4*i+2)
		} else {
			if f.numHMetrics > 0 {
				f.advances[i] = f.advances[f.numHMetrics-1]
			}
			off := 4*f.numHMetrics + 2*(i-f.numHMetrics)
			f.lsbs[i] = i16(hmtx, off)
		}
	}
	return f, nil
}

func (f *ttfFont) parseKern(kern []byte) error {
	if len(kern) < 4 {
		return errors.New("freetype: invalid TrueType format: kern data too short")
	}
	nTables := int(u16(kern, 2))
	off := 4
	for i := 0; i < nTables; i++ {
		if off+6 > len(kern) {
			return errors.New("freetype: invalid TrueType format: kern data too short")
		}
		length := int(u16(kern, off))
		coverage := u16(kern, off+2)
