{"command":"cat > glyph.go <<'GO'
package main

import (
	"math"
	"sort"
)

type outlinePoint struct {
	x, y float64
	on   bool
}

type glyphOutline struct {
	contours [][]outlinePoint
	advance  int
}

func (f *ttfFont) locaOffset(gid int) (int, int, bool) {
	loca := f.tables["loca"]
	if gid < 0 || gid >= f.numGlyphs {
		return 0, 0, false
	}
	if f.indexToLocFormat == 0 {
		if len(loca) < 2*(gid+2) {
			return 0, 0, false
		}
		return int(u16(loca, 2*gid)) * 2, int(u16(loca, 2*gid+2)) * 2, true
	}
	if len(loca) < 4*(gid+2) {
		return 0, 0, false
	}
	return int(u32(loca, 4*gid)), int(u32(loca, 4*gid+4)), true
}

func (f *ttfFont) glyphOutline(gid int) glyphOutline {
	return f.glyphOutlineDepth(gid, 0)
}

func (f *ttfFont) glyphOutlineDepth(gid, depth int) glyphOutline {
	out := glyphOutline{}
	if gid >= 0 && gid < len(f.advances) {
		out.advance = int(f.advances[gid])
	}
	if depth > 8 {
		return out
	}
	start, end, ok := f.locaOffset(gid)
	if !ok || start == end {
		return out
	}
	glyf := f.tables["glyf"]
	if start < 0 || end < start || end > len(glyf) || end-start < 10 {
		return out
	}
	g := glyf[start:end]
	nContours := int(i16(g, 0))
	if nContours >= 0 {
		return f.simpleGlyph(g, nContours, out.advance)
	}
	// Composite glyph.
	out.contours = nil
	off := 10
	for {
		if off+4 > len(g) {
			break
		}
		flags := u16(g, off)
		compGid := int(u16(g, off+2))
		off += 4
		var arg1, arg2 int
		if flags&0x0001 != 0 {
			if off+4 > len(g) {
				break
			}
			arg1 = int(i16(g, off))
			arg2 = int(i16(g, off+2))
			off += 4
		} else {
			if off+2 > len(g) {
				break
			}
			arg1 = int(int8(g[off]))
			arg2 = int(int8(g[off+1]))
			off += 2
		}
		a, b, c, d := 1.0, 0.0, 0.0, 1.0
		readFixed := func() float64 {
			v := int16(u16(g, off))
			off += 2
			return float64(v) / 16384.0
		}
		if flags&0x0008 != 0 {
			if off+2 > len(g) {
				break
			}
			s := readFixed()
			a, d = s, s
		} else if flags&0x0040 != 0 {
			if off+4 > len(g) {
				break
			}
			a = readFixed()
			d = readFixed()
		} else if flags&0x0080 != 0 {
			if off+8 > len(g) {
				break
			}
			a = readFixed()
			b = readFixed()
			c = readFixed()
			d = readFixed()
		}
		comp := f.glyphOutlineDepth(compGid, depth+1)
		// Transform a copy of the component's points.
		transformed := make([][]outlinePoint, len(comp.contours))
		for ci, contour := range comp.contours {
			tc := make([]outlinePoint, len(contour))
			for i, p := range contour {
				tc[i] = outlinePoint{x: a*p.x + b*p.y, y: c*p.x + d*p.y, on: p.on}
			}
			transformed[ci] = tc
		}
		dx, dy := float64(arg1), float64(arg2)
		if flags&0x0002 == 0 {
			// Point-matching: arg1 is a point in the accumulated
			// outline, arg2 a point in the component.
			var basePts []outlinePoint
			for _, cont := range out.contours {
				basePts = append(basePts, cont...)
			}
			var compPts []outlinePoint
			for _, cont := range transformed {
				compPts = append(compPts, cont...)
			}
			if arg1 >= 0 && arg1 < len(basePts) && arg2 >= 0 && arg2 < len(compPts) {
				dx = basePts[arg1].x - compPts[arg2].x
				dy = basePts[arg1].y - compPts[arg2].y
			} else {
				dx, dy = 0, 0
			}
		}
		for _, contour := range transformed {
			for i := range contour {
				contour[i].x += dx
				contour[i].y += dy
			}
			out.contours = append(out.contours, contour)
		}
		if flags&0x0020 == 0 {
			break
		}
	}
	return out
}

func (f *ttfFont) simpleGlyph(g []byte, nContours int, advance int) glyphOutline {
	out := glyphOutline{advance: advance}
	if nContours == 0 {
		return out
	}
	if len(g) < 10+2*nContours {
		return out
	}
