				break
			}
			arg1 = int(i16(g, off))
			arg2 = int(i16(g, off+2))
			off += 4
		} else {
			if off+2 > len(g) {
				break
			}
			arg1 = int(int8(g[off]))
			arg2 = int(int8(g[off+1]))
			off += 2
		}
		a, b, c, d := 1.0, 0.0, 0.0, 1.0
		readFixed := func() float64 {
			v := int16(u16(g, off))
			off += 2
			return float64(v) / 16384.0
		}
		if flags&0x0008 != 0 {
			if off+2 > len(g) {
				break
			}
			s := readFixed()
			a, d = s, s
		} else if flags&0x0040 != 0 {
			if off+4 > len(g) {
				break
			}
			a = readFixed()
			d = readFixed()
		} else if flags&0x0080 != 0 {
			if off+8 > len(g) {
				break
			}
			a = readFixed()
			b = readFixed()
			c = readFixed()
			d = readFixed()
		}
		comp := f.glyphOutlineDepth(compGid, depth+1)
		// Transform a copy of the component's points.
		transformed := make([][]outlinePoint, len(comp.contours))
		for ci, contour := range comp.contours {
			tc := make([]outlinePoint, len(contour))
			for i, p := range contour {
				tc[i] = outlinePoint{x: a*p.x + b*p.y, y: c*p.x + d*p.y, on: p.on}
			}
			transformed[ci] = tc
		}
		dx, dy := float64(arg1), float64(arg2)
		if flags&0x0002 == 0 {
			// Point-matching: arg1 is a point in the accumulated
			// outline, arg2 a point in the component.
			var basePts []outlinePoint
			for _, cont := range out.contours {
				basePts = append(basePts, cont...)
			}
			var compPts []outlinePoint
			for _, cont := range transformed {
				compPts = append(compPts, cont...)
			}
			if arg1 >= 0 && arg1 < len(basePts) && arg2 >= 0 && arg2 < len(compPts) {
				dx = basePts[arg1].x - compPts[arg2].x
				dy = basePts[arg1].y - compPts[arg2].y
			} else {
				dx, dy = 0, 0
			}
		}
		for _, contour := range transformed {
			for i := range contour {
				contour[i].x += dx
				contour[i].y += dy
			}
			out.contours = append(out.contours, contour)
		}
		if flags&0x0020 == 0 {
			break
		}
	}
	return out
}

func (f *ttfFont) simpleGlyph(g []byte, nContours int, advance int) glyphOutline {
	out := glyphOutline{advance: advance}
	if nContours == 0 {
		return out
	}
	if len(g) < 10+2*nContours {
		return out
	}
	endPts := make([]int, nContours)
	total := 0
	for i := 0; i < nContours; i++ {
		endPts[i] = int(u16(g, 10+2*i))
		if endPts[i]+1 > total {
			total = endPts[i] + 1
		}
	}
	off := 10 + 2*nContours
	if off+2 > len(g) {
		return out
	}
	instLen := int(u16(g, off))
	off += 2 + instLen
	if off > len(g) {
		return out
	}
	flags := make([]byte, 0, total)
	for len(flags) < total {
		if off >= len(g) {
			return out
		}
		fl := g[off]
		off++
		flags = append(flags, fl)
		if fl&8 != 0 {
			if off >= len(g) {
				return out
			}
			rep := int(g[off])
			off++
			for i := 0; i < rep && len(flags) < total; i++ {
				flags = append(flags, fl)
			}
		}
	}
	xs := make([]float64, total)
	x := 0
	for i := 0; i < total; i++ {
		fl := flags[i]
		if fl&2 != 0 {
			if off >= len(g) {
				return out
			}
			d := int(g[off])
			off++
			if fl&16 == 0 {
				d = -d
			}
			x += d
		} else if fl&16 == 0 {
			if off+1 >= len(g) {
				return out
			}
			x += int(i16(g, off))
			off += 2
		}
		xs[i] = float64(x)
	}
	ys := make([]float64, total)
	y := 0
	for i := 0; i < total; i++ {
		fl := flags[i]
		if fl&4 != 0 {
			if off >= len(g) {
				return out
			}
			d := int(g[off])
			off++
			if fl&32 == 0 {
				d = -d
			}
			y += d
		} else if fl&32 == 0 {
			if off+1 >= len(g) {
				return out
			}
			y += int(i16(g, off))
			off += 2
		}
		ys[i] = float64(y)
	}
	start := 0
	for _, end := range endPts {
		if end < start || end >= total {
			continue
		}
		var contour []outlinePoint
		for i := start; i <= end; i++ {
			contour = append(contour, outlinePoint{x: xs[i], y: ys[i], on: flags[i]&1 != 0})
		}
		out.contours = append(out.contours, contour)
		start = end + 1
	}
	return out
}

type segment struct{ x0, y0, x1, y1 float64 }

func midpoint(a, b outlinePoint) outlinePoint {
	return outlinePoint{x: (a.x + b.x) / 2, y: (a.y + b.y) / 2, on: true}
}

func flattenQuad(p0, p1, p2 outlinePoint, segs *[]segment, depth int) {
	// Flatness: distance of control point from midpoint of endpoints.
	mx := (p0.x + p2.x) / 2
	my := (p0.y + p2.y) / 2
	d := math.Hypot(p1.x-mx, p1.y-my)
	if d < 0.08 || depth >= 12 {
		*segs = append(*segs, segment{p0.x, p0.y, p2.x, p2.y})
		return
	}
	q0 := outlinePoint{x: (p0.x + p1.x) / 2, y: (p0.y + p1.y) / 2}
	q1 := outlinePoint{x: (p1.x + p2.x) / 2, y: (p1.y + p2.y) / 2}
	m := outlinePoint{x: (q0.x + q1.x) / 2, y: (q0.y + q1.y) / 2}
	flattenQuad(p0, q0, m, segs, depth+1)
	flattenQuad(m, q1, p2, segs, depth+1)
}

// outlineSegments converts scaled glyph outlines (already in pixel
// coordinates with y down) to line segments.
func outlineSegments(contours [][]outlinePoint) []segment {
	var segs []segment
	for _, contour := range contours {
		if len(contour) == 0 {
			continue
		}
		// Normalise: ensure the contour starts with an on-curve point.
		pts := append([]outlinePoint(nil), contour...)
		if !pts[0].on {
			last := pts[len(pts)-1]
			if last.on {
				pts = append([]outlinePoint{last}, pts[:len(pts)-1]...)
			} else {
				pts = append([]outlinePoint{midpoint(last, pts[0])}, pts...)
			}
		}
		cur := pts[0]
		i := 1
		for i < len(pts) {
			p := pts[i]
			if p.on {
				segs = append(segs, segment{cur.x, cur.y, p.x, p.y})
				cur = p
				i++
			} else {
				var next outlinePoint
				if i+1 < len(pts) {
					next = pts[i+1]
					if !next.on {
						next = midpoint(p, next)
					} else {
						i++ // consume the on-curve end point below via cur
					}
				} else {
					next = pts[0]
				}
				flattenQuad(cur, p, next, &segs, 0)
				cur = next
				i++
			}
		}
		if cur != pts[0] {
			segs = append(segs, segment{cur.x, cur.y, pts[0].x, pts[0].y})
		}
	}
	return segs
}

// rasterizeSegments computes 0-255 coverage for pixels in the given bounds
// using 16 vertical subsamples with exact horizontal interval coverage.
func rasterizeSegments(segs []segment, minX, minY, w, h int) []byte {
	alpha := make([]byte, w*h)
	const sub = 16
	for row := 0; row < h; row++ {
		yBase := float64(minY + row)
		cover := make([]float64, w)
		for s := 0; s < sub; s++ {
			y := yBase + (float64(s)+0.5)/sub
			type cross struct {
				x    float64
				wind int
			}
			var crosses []cross
			for _, e := range segs {
				if e.y0 == e.y1 {
					continue
				}
				lo, hi := e.y0, e.y1
				if lo > hi {
					lo, hi = hi, lo
				}
				if y < lo || y >= hi {
					continue
				}
				t := (y - e.y0) / (e.y1 - e.y0)
				x := e.x0 + t*(e.x1-e.x0)
				wind := 1
				if e.y1 < e.y0 {
					wind = -1
				}
				crosses = append(crosses, cross{x, wind})
			}
			if len(crosses) == 0 {
				continue
			}
			sort.Slice(crosses, func(i, j int) bool { return crosses[i].x < crosses[j].x })
			wind := 0
			for ci := 0; ci+1 < len(crosses); ci++ {
				wind += crosses[ci].wind
				if wind == 0 {
					continue
				}
				x0 := crosses[ci].x
				x1 := crosses[ci+1].x
				if x1 <= float64(minX) || x0 >= float64(minX+w) {
					continue
				}
				if x0 < float64(minX) {
					x0 = float64(minX)
				}
				if x1 > float64(minX+w) {
					x1 = float64(minX + w)
				}
				// Add [x0,x1] to cover.
				for px := int(math.Floor(x0)) - minX; px < w && float64(minX+px) < x1; px++ {
					if px < 0 {
						continue
					}
					left := math.Max(x0, float64(minX+px))
					right := math.Min(x1, float64(minX+px+1))
					if right > left {
						cover[px] += (right - left) / sub
					}
				}
			}
		}
		for x := 0; x < w; x++ {
			v := int(math.Floor(cover[x]*255 + 0.5))
			if v > 255 {
				v = 255
			}
			if v < 0 {
				v = 0
			}
			alpha[row*w+x] = byte(v)
		}
	}
	return alpha
}
