package main

import (
	"image"
	"math"
)

type customGlyph struct {
	mask   *image.Alpha
	offset image.Point // mask origin relative to (dotX, floor(baseline))
}

var customGlyphCache = map[string]customGlyph{}

func customGlyphFor(font *loadedFont, r rune, sizePx float64, baselineFrac float64) customGlyph {
	key := font.path + "|" + string(rune(int(sizePx*64))) + string(r)
	// The key above intentionally uses the rune itself as the last
	// component; collisions across sizes are avoided by the size rune.
	if g, ok := customGlyphCache[key]; ok {
		return g
	}
	f := font.ttf
	gid := f.glyphIndex(r)
	outline := f.glyphOutline(gid)
	if len(outline.contours) == 0 {
		customGlyphCache[key] = customGlyph{}
		return customGlyph{}
	}
	scale := sizePx / float64(maxInt(f.unitsPerEm, 1))
	scaled := make([][]outlinePoint, len(outline.contours))
	minX, minY := math.Inf(1), math.Inf(1)
	maxX, maxY := math.Inf(-1), math.Inf(-1)
	for i, cont := range outline.contours {
		sc := make([]outlinePoint, len(cont))
		for j, p := range cont {
			x := p.x * scale
			y := baselineFrac - p.y*scale
			sc[j] = outlinePoint{x: x, y: y, on: p.on}
			if x < minX {
				minX = x
			}
			if x > maxX {
				maxX = x
			}
			if y < minY {
				minY = y
			}
			if y > maxY {
				maxY = y
			}
		}
		scaled[i] = sc
	}
	segs := outlineSegments(scaled)
	if len(segs) == 0 {
		customGlyphCache[key] = customGlyph{}
		return customGlyph{}
	}
	// Recompute bounds from segments (curves may exceed control bounds
	// only within control-point bounds, so this is safe and tight).
	minX, minY = math.Inf(1), math.Inf(1)
	maxX, maxY = math.Inf(-1), math.Inf(-1)
	for _, s := range segs {
		minX = math.Min(minX, math.Min(s.x0, s.x1))
		maxX = math.Max(maxX, math.Max(s.x0, s.x1))
		minY = math.Min(minY, math.Min(s.y0, s.y1))
		maxY = math.Max(maxY, math.Max(s.y0, s.y1))
	}
	ix0 := int(math.Floor(minX))
	iy0 := int(math.Floor(minY))
	ix1 := int(math.Ceil(maxX))
	iy1 := int(math.Ceil(maxY))
	w, h := ix1-ix0, iy1-iy0
	if w <= 0 || h <= 0 {
		customGlyphCache[key] = customGlyph{}
		return customGlyph{}
	}
	alpha := rasterizeSegments(segs, ix0, iy0, w, h)
	g := customGlyph{
		mask:   &image.Alpha{Pix: alpha, Stride: w, Rect: image.Rect(0, 0, w, h)},
		offset: image.Pt(ix0, iy0),
	}
	customGlyphCache[key] = g
	return g
}

func maxInt(a, b int) int {
	if a > b {
		return a
	}
	return b
}
