func scaledGlyphMask(r rune, braille bool, scale float64) *image.Alpha {
	base := glyphMask(r, braille)
	if base == nil {
		return nil
	}
	if scale == 1 {
		return &image.Alpha{Pix: append([]byte(nil), base...), Stride: 24, Rect: image.Rect(0, 0, 24, 38)}
