	base := glyphMask(r, braille)
	if base == nil {
		return nil
	}
	if scale == 1 {
		return &image.Alpha{Pix: append([]byte(nil), base...), Stride: 24, Rect: image.Rect(0, 0, 24, 38)}
	}
	sw := int(math.Round(24 * scale))
	sh := int(math.Round(38 * scale))
	if sw < 1 {
		sw = 1
	}
	if sh < 1 {
		sh = 1
	}
	key := fmt.Sprintf("%d|%v|%dx%d", r, braille, sw, sh)
	if m, ok := scaledGlyphCache[key]; ok {
		return m
	}
	var pix []byte
	if scale > 1 {
		// Lanczos upscaling keeps glyph edges comparatively sharp.
		grid := &pixelGrid{W: 24, H: 38, Max: 255, Pix: make([]Pixel, 24*38)}
		for i, a := range base {
			grid.Pix[i] = Pixel{R: uint32(a), G: uint32(a), B: uint32(a), A: 255}
		}
		resized := resizePixelGrid(grid, sw, sh)
		pix = make([]byte, sw*sh)
		for i, p := range resized.Pix {
			pix[i] = uint8(p.R)
		}
	} else {
		pix = make([]byte, sw*sh)
		for y := 0; y < sh; y++ {
			sy := (float64(y)+0.5)*38/float64(sh) - 0.5
			y0 := int(math.Floor(sy))
			fy := sy - float64(y0)
			for x := 0; x < sw; x++ {
