{"command":"cat > completion_compat.go <<'GO'
package main

import (
	"fmt"
	"os"
	"strings"
)

var completionLongFlags = map[string]bool{ // value: requires a value
	"color": false, "color-bg": false, "dimensions": true, "width": true,
	"height": true, "map": true, "braille": false, "threshold": true,
	"dither": false, "grayscale": false, "complex": false, "full": false,
	"negative": false, "flipX": false, "flipY": false, "save-img": true,
	"save-txt": true, "save-gif": true, "save-bg": true, "font": true,
	"font-color": true, "only-save": false, "formats": false,
	"help": false, "version": false,
}

var completionShortFlags = map[byte]bool{ // value: requires a value
	'C': false, 'd': true, 'W': true, 'H': true, 'm': true, 'b': false,
	'g': false, 'c': false, 'f': false, 'n': false, 'x': false, 'y': false,
	's': true, 'h': false, 'v': false,
}

// stripFlagCommands returns non-flag arguments in the manner of the older
// Cobra completion implementation used by the reference.
func stripFlagCommands(args []string) []string {
	var cmds []string
	for i := 0; i < len(args); i++ {
		s := args[i]
		if s == "--" {
			break
		}
		if strings.HasPrefix(s, "--") {
			name := s[2:]
			hasEq := strings.Contains(name, "=")
			if hasEq {
				name = strings.SplitN(name, "=", 2)[0]
			}
			needs, known := completionLongFlags[name]
			if !hasEq && (!known || needs) {
				i++ // skip the presumed value
			}
			continue
		}
		if strings.HasPrefix(s, "-") && s != "-" {
			consumedNext := false
			for j := 1; j < len(s); j++ {
				needs, known := completionShortFlags[s[j]]
				if !known {
					if j == len(s)-1 {
						consumedNext = true
					}
					break
				}
				if needs {
					if j == len(s)-1 {
						consumedNext = true
					}
					break
				}
			}
			if consumedNext {
				i++
			}
			continue
		}
		if s == "-" {
			continue
		}
		cmds = append(cmds, s)
	}
	return cmds
}

// handleCompletionCompat reproduces the completion behaviour of Cobra
// 1.1.x for the cases where newer Cobra differs: positional arguments
// before the word being completed, a trailing "--", and the old
// "does not support flag" diagnostic for a trailing unknown flag.
func handleCompletionCompat() {
	if len(os.Args) < 3 || (os.Args[1] != "__complete" && os.Args[1] != "__completeNoDesc") {
		return
	}
	args := os.Args[2:]
	if len(args) == 0 {
		return
	}
	trimmed := args[:len(args)-1]
	toComplete := args[len(args)-1]

	if cmds := stripFlagCommands(trimmed); len(cmds) > 0 {
		fmt.Println(":0")
		fmt.Fprintf(os.Stderr, "[Debug] [Error] Unable to find a command for arguments: %v\nCompletion ended with directive: ShellCompDirectiveDefault\n", trimmed)
		os.Exit(0)
	}

	if !strings.HasPrefix(toComplete, "-") && len(trimmed) > 0 {
		last := trimmed[len(trimmed)-1]
		if strings.HasPrefix(last, "-") && last != "-" && last != "--" && !strings.Contains(last, "=") {
			name := strings.TrimLeft(last, "-")
			_, longKnown := completionLongFlags[name]
			_, shortKnown := completionShortFlags[0]
			if len(name) == 1 {
				_, shortKnown = completionShortFlags[name[0]]
			} else {
				shortKnown = false
			}
			if !longKnown && !shortKnown {
				fmt.Println(":0")
				fmt.Fprintf(os.Stderr, "[Debug] [Error] Subcommand 'ascii-image-converter' does not support flag '%s'\nCompletion ended with directive: ShellCompDirectiveDefault\n", name)
				os.Exit(0)
			}
		}
	}

	// Older Cobra completed flags even if a "--" appeared before the
	// word being completed. Remove the first such token so that the
	// newer Cobra implementation does the same.
	if strings.HasPrefix(toComplete, "-") {
		for i, tok := range trimmed {
			if tok == "--" {
				idx := 2 + i
				os.Args = append(os.Args[:idx], os.Args[idx+1:]...)
				break
			}
		}
	}
}
