 def ch(t,d):return struct.pack('>I',len(d))+t+d+struct.pack('>I',zlib.crc32(t+d)&0xffffffff)
 raw=b'\x00'+b''.join(bytes([v,v,v]) for v in vals);ih=struct.pack('>IIBBBBB',len(vals),1,8,2,0,0,0);open(path,'wb').write(b'\x89PNG\r\n\x1a\n'+ch(b'IHDR',ih)+ch(b'IDAT',zlib.compress(raw))+ch(b'IEND',b''))
env=dict(os.environ,COLORTERM='truecolor')
patterns={
 'grad':list(range(256)),
 'step':[0]*128+[255]*128,
 'checker':[0,255]*128,
 'formula':[(i*37+((i*i)>>3))%256 for i in range(256)],
 'blocks':[(255 if (i//16)%2 else 0) for i in range(256)],
}
rows=[]
for name,vals in patterns.items():
 write('/tmp/pat.png',vals)
 for outw in [1,2,3,4,5,7,8,10,16,20,32,50,64,100,128,200,256,300]:
  out=subprocess.check_output(['/tmp/ref_executable','/tmp/pat.png','-d',f'{outw},1','-C'],env=env).decode();res=[int(x) for x in re.findall(r'38;2;(\d+);',out)];rows.append([name,outw]+res)
with open('/tmp/resize_ref.csv','w',newline='') as f:csv.writer(f).writerows(rows)
print('rows',len(rows))
