package main
import("bufio";"fmt";"math";"os";"strconv";"strings")
func sincA(x float64)float64{if x==0{return 1};return math.Sin(math.Pi*x)/(math.Pi*x)}
func lancA(x float64)float64{if x==0{return 1};if math.Abs(x)>=3{return 0};return sincA(x)*sincA(x/3)}
func lancB(x float64)float64{if x==0{return 1};if math.Abs(x)>=3{return 0};return (math.Sin(math.Pi*x)/(math.Pi*x))*(math.Sin(math.Pi*x/3)/(math.Pi*x/3))}
func lancC(x float64)float64{if x<0{x=-x};if x==0{return 1};if x>=3{return 0};return sincA(x)*sincA(x/3)}
func q(v float64)int{if v<0{return 0};if v>255{return 255};return int(math.Floor(v+.5))}
type cand struct{name string;center32 bool;kernel int;mode string}
func weights(inn,outn,j int,c cand)([]int,[]float64){
 scale:=float64(inn)/float64(outn);fs:=math.Max(1,scale);cen:=(float64(j)+.5)*scale-.5
 if c.center32{scale=float64(float32(inn)/float32(outn));fs=float64(float32(math.Max(1,scale)));cen=float64((float32(j)+.5)*float32(scale)-.5)}
 sup:=3*fs;st:=int(math.Ceil(cen-sup));if st<0{st=0};en:=int(math.Floor(cen+sup));if en>=inn{en=inn-1}
 var idx []int;var ws []float64
 for i:=st;i<=en;i++{arg:=(float64(i)-cen)/fs;if c.center32{arg=float64((float32(i)-float32(cen))/float32(fs))};var w float64;switch c.kernel{case 0:w=lancA(arg);case 1:w=lancB(arg);default:w=lancC(arg)};if w!=0{idx=append(idx,i);ws=append(ws,w)}}
 return idx,ws
}
func eval(vals []float64,outn,j int,c cand)int{
 idx,ws:=weights(len(vals),outn,j,c)
 switch c.mode{
 case "norm64_direct":
  sum:=0.;for _,w:=range ws{sum+=w};s:=0.;for k,i:=range idx{s+=(ws[k]/sum)*vals[i]};return q(s)
 case "norm64_proper":
  sum:=0.;for _,w:=range ws{sum+=w};sp:=0.;sa:=0.;for k,i:=range idx{w:=ws[k]/sum;sp+=w*vals[i];sa+=w*255};return q(sp*255/sa)
 case "raw64_direct":
  sum:=0.;s:=0.;for k,i:=range idx{sum+=ws[k];s+=ws[k]*vals[i]};return q(s/sum)
 case "raw64_proper":
  sp:=0.;sa:=0.;for k,i:=range idx{sp+=ws[k]*vals[i];sa+=ws[k]*255};return q(sp*255/sa)
 case "f32w_norm64_direct":
  sum:=0.;for _,w:=range ws{sum+=w};s:=0.;for k,i:=range idx{s+=float64(float32(ws[k]/sum))*vals[i]};return q(s)
 case "f32w_norm64_proper":
  sum:=0.;for _,w:=range ws{sum+=w};sp:=0.;sa:=0.;for k,i:=range idx{w:=float64(float32(ws[k]/sum));sp+=w*vals[i];sa+=w*255};return q(sp*255/sa)
 case "f32w_f32tot_direct64":
  var tot float32;fw:=make([]float32,len(ws));for i,w:=range ws{fw[i]=float32(w);tot+=fw[i]};s:=0.;for k,i:=range idx{s+=float64(fw[k]/tot)*vals[i]};return q(s)
 case "f32w_f32tot_proper64":
  var tot float32;fw:=make([]float32,len(ws));for i,w:=range ws{fw[i]=float32(w);tot+=fw[i]};sp:=0.;sa:=0.;for k,i:=range idx{w:=float64(fw[k]/tot);sp+=w*vals[i];sa+=w*255};return q(sp*255/sa)
 case "f32all_direct":
  var tot float32;fw:=make([]float32,len(ws));for i,w:=range ws{fw[i]=float32(w);tot+=fw[i]};for i:=range fw{fw[i]/=tot};var s float32;for k,i:=range idx{s+=fw[k]*float32(vals[i])};return q(float64(s))
 case "f32all_proper":
  var tot float32;fw:=make([]float32,len(ws));for i,w:=range ws{fw[i]=float32(w);tot+=fw[i]};for i:=range fw{fw[i]/=tot};var sp,sa float32;for k,i:=range idx{sp+=fw[k]*float32(vals[i]);sa+=fw[k]*255};return q(float64(sp*255/sa))
 case "f32all_raw_proper":
  fw:=make([]float32,len(ws));for i,w:=range ws{fw[i]=float32(w)};var sp,sa float32;for k,i:=range idx{sp+=fw[k]*float32(vals[i]);sa+=fw[k]*255};return q(float64(sp*255/sa))
 case "f32all_raw_direct":
  fw:=make([]float32,len(ws));for i,w:=range ws{fw[i]=float32(w)};var s,tot float32;for k,i:=range idx{s+=fw[k]*float32(vals[i]);tot+=fw[k]};return q(float64(s/tot))
 }
 return -1
}
func patVals(name string)[]float64{
 v:=make([]float64,256)
 switch name{
 case "grad":for i:=range v{v[i]=float64(i)}
 case "step":for i:=128;i<256;i++{v[i]=255}
 case "checker":for i:=range v{if i%2==1{v[i]=255}}
 case "formula":for i:=range v{v[i]=float64((i*37+((i*i)>>3))%256)}
 case "blocks":for i:=range v{if (i/16)%2==1{v[i]=255}}
 }
 return v
}
func main(){
 f,_:=os.Open("/tmp/resize_ref.csv");sc:=bufio.NewScanner(f);sc.Buffer(make([]byte,1024*1024),1024*1024)
 type row struct{name string;out int;vals []int};var rows []row
 for sc.Scan(){p:=strings.Split(sc.Text(),",");out,_:=strconv.Atoi(p[1]);var vals []int;for _,s:=range p[2:]{n,_:=strconv.Atoi(s);vals=append(vals,n)};rows=append(rows,row{p[0],out,vals})}
 modes:=[]string{"norm64_direct","norm64_proper","raw64_direct","raw64_proper","f32w_norm64_direct","f32w_norm64_proper","f32w_f32tot_direct64","f32w_f32tot_proper64","f32all_direct","f32all_proper","f32all_raw_proper","f32all_raw_direct"}
 for _,c32:=range []bool{false,true}{
  for k:=0;k<3;k++{
   for _,m:=range modes{
    c:=cand{"",c32,k,m};diffpix:=0;total:=0;abs:=0
    for _,r:=range rows{vals:=patVals(r.name);for j,exp:=range r.vals{got:=eval(vals,r.out,j,c);total++;if got!=exp{diffpix++;d:=got-exp;if d<0{d=-d};abs+=d}}}
    fmt.Printf("center32=%v kernel=%d mode=%-28s diffpix=%3d/%d abs=%d\n",c32,k,m,diffpix,total,abs)
   }
  }
 }
}
