go run score_candidates.go > /tmp/cand_scores.txt; sort -k5 -n /tmp/cand_scores.txt 2>/dev/null | head; grep "diffpix=" /tmp/cand_scores.txt | sed 's/.*diffpix=//' | sort -n | head
cat /tmp/cand_scores.txt
