 type row struct{name string;out int;vals []int};var rows []row
 for sc.Scan(){p:=strings.Split(sc.Text(),",");out,_:=strconv.Atoi(p[1]);var vals []int;for _,s:=range p[2:]{n,_:=strconv.Atoi(s);vals=append(vals,n)};rows=append(rows,row{p[0],out,vals})}
 modes:=[]string{"norm64_direct","norm64_proper","raw64_direct","raw64_proper","f32w_norm64_direct","f32w_norm64_proper","f32w_f32tot_direct64","f32w_f32tot_proper64","f32all_direct","f32all_proper","f32all_raw_proper","f32all_raw_direct"}
 for _,c32:=range []bool{false,true}{
  for k:=0;k<3;k++{
   for _,m:=range modes{
    c:=cand{"",c32,k,m};diffpix:=0;total:=0;abs:=0
    for _,r:=range rows{vals:=patVals(r.name);for j,exp:=range r.vals{got:=eval(vals,r.out,j,c);total++;if got!=exp{diffpix++;d:=got-exp;if d<0{d=-d};abs+=d}}}
    fmt.Printf("center32=%v kernel=%d mode=%-28s diffpix=%3d/%d abs=%d\n",c32,k,m,diffpix,total,abs)
   }
  }
 }
}
